/* MeenLearn · lessons 2/3 — CSS (20) + JavaScript (20) */
window.MEEN_LESSONS_2 = {

  css: [
    { t: "What CSS is and how it connects to HTML",
      opt: ["vscode"],
      text: "CSS (Cascading Style Sheets) controls how HTML looks: colors, spacing, layout, fonts and motion. A CSS rule is a selector (which elements) plus a block of properties (what to change): p { color: teal; }. The professional setup is a separate file linked from <head> with <link rel=\"stylesheet\" href=\"style.css\"> — one stylesheet, many pages, easy to change the whole site in one place.",
      def: "CSS is the language of page presentation: rules that pair a selector with property:value declarations to control appearance and layout.",
      code: "/* in style.css */\nbody {\n  font-family: Georgia, serif;\n  background: #faf7f0;\n  color: #20232b;\n}\n\nh1 {\n  color: #b3543c;\n  font-size: 32px;\n}\n\n/* in HTML <head> */\n<link rel=\"stylesheet\"\n      href=\"style.css\">\n\nSelector -> which elements.\nBlock -> what changes.",
      out: { web: { h: "<h1>The rule, applied</h1><p>This paragraph gets its color from a CSS rule: p { color: ... }. No inline style, no attribute — just a selector and a property.</p>", c: "body{font-family:Georgia,serif;background:#faf7f0;color:#20232b;padding:24px;margin:0} h1{color:#b3543c;font-size:32px} p{color:#3a5fa0;line-height:1.6}", j: "" } },
      flow: ["Write rules", "link the file", "selector matches", "properties apply"],
      task: "Create style.css with one rule for body and one for h1. Link it from <head>. Change h1's color in the file — does the page update without touching the HTML?",
      mistake: "Putting styles in style=\"...\" attributes on every element (inline styles win over the stylesheet, so your later rules can't reach them, and the design is scattered across the page). Keep styling in the stylesheet; inline is for one-offs at most.",
      tip: "The \"C\" in CSS stands for cascading: multiple rules can target the same element, and a priority system decides the winner. You'll meet it formally later — for now, know that \"my CSS isn't working\" usually means a different rule is winning.",
      challenge: "You have <h1> styled by an element rule, and the same <h1> also has class=\"title\" with a class rule. Which color wins if the two disagree — and why (hint: specificity)?" },

    { t: "Selectors: targeting exactly what you mean",
      text: "Selectors pick which elements a rule applies to. The basics: p (every paragraph), .card (every element with class=\"card\"), #logo (the one element with id=\"logo\"). Combine them: nav a (links inside nav), .card:hover (a card being hovered), h1, h2, h3 (multiple in one rule). Specificity decides conflicts: id beats class beats element — remember that order and most \"why doesn't this work?\" questions answer themselves.",
      def: "A selector identifies the elements a rule targets: element (p), class (.card), id (#logo), combined (nav a, .card:hover).",
      code: "p          { color: #555; }   /* all <p> */\n.card     { border: 1px solid; } /* .card */\n#logo      { width: 40px; }    /* #logo */\n\nnav a      { color: teal; }    /* a inside nav */\n.card:hover{ transform: ...; } /* .card + state */\n\nh1, h2, h3 { font-family: ...; } /* group */\n\nWinner on conflict:\nid > class > element > *",
      out: { web: { h: "<div class=\"card\" id=\"logo\">Class .card + id #logo (div)</div><p class=\"card\">Class .card (also a p)</p><p>Just a p (element selector)</p><nav>nav a demo: <a href=\"#\">link inside nav</a></nav>", c: "body{font-family:sans-serif;background:#faf7f0;padding:24px;color:#222} p{color:#555;border:1px dashed #ccc;padding:8px;border-radius:6px;margin:8px 0} .card{border:2px solid #5E8CE6;background:#eef3fb;padding:8px;border-radius:6px} #logo{border-color:#f5b23d;font-weight:bold} nav a{color:#2c8a63;font-weight:bold} .card:hover{background:#f5b23d33} a{color:#3a5fa0}", j: "" } },
      flow: ["element / .class / #id", "combine for precision", "states: :hover :focus", "specificity resolves fights"],
      task: "Style a page with three rules that overlap on one element (an element rule, a class rule, and an id rule for the same color). Predict which wins, verify in DevTools, then swap the id to a different element — does the answer change?",
      mistake: "Writing body { color: red } but the text stays default because a more specific rule (or a later rule) is overriding it. Open DevTools: the winning property is bold, losers are crossed out with the rule named. Read that list before changing anything.",
      tip: "Prefer classes over ids for styling: classes are repeatable and themable, ids are for unique anchors. Reach for an id selector only when you truly mean exactly one element.",
      challenge: "Why does .menu .item not match <div class=\"menu item\"> on the same element? (Hint: what does a space between selectors mean?) What selector WOULD match that element?" },

    { t: "Colors and units: the measurement system",
      text: "Colors: named (teal), hex (#F5B23D — six digits, RR GGBB), rgb/rgba with alpha (rgb(245,178,61,0.5)), or hsl. Modern CSS adds color-mix() to blend two colors. Units measure everything else: px (fixed), % (of the parent), rem (of the root font size — use for text), vw/vh (of the viewport), fr (grid fractions). Mixing the right unit per job is what makes layouts flexible.",
      def: "Colors are named, hex, rgb(a), or hsl values; sizes use px, %, rem, em, vw/vh and fr — each relative to a different base.",
      code: "color: teal;\ncolor: #F5B23D;       /* hex */\ncolor: rgb(245 178 61);\ncolor: rgba(245 178 61 / .5);  /* +alpha */\ncolor: color-mix(in srgb, teal 50%, gold);\n\nUnits:\n  px    fixed\n  %     of parent\n  rem   of root font (16px default)\n  em    of this element's font\n  vw/vh of the viewport\n  fr    grid fractions only",
      out: { web: { h: "<div class=\"swatches\"><span class=\"s\" style=\"background:#F5B23D\" title=\"hex\">#F5B23D</span><span class=\"s\" style=\"background:rgb(111 195 176)\" title=\"rgb\">rgb()</span><span class=\"s\" style=\"background:rgba(111 195 176 / .5)\" title=\"rgba\">+ alpha</span><span class=\"s\" style=\"background:color-mix(in srgb, #F5B23D 50%, #6fc3b0)\" title=\"mix\">mix()</span></div><p style=\"font-size:14px;margin-top:12px\">The last one blends gold and teal 50/50 with color-mix().</p>", c: "body{font-family:sans-serif;background:#14171f;color:#eceae3;padding:24px} .swatches{display:flex;gap:8px;flex-wrap:wrap} .s{width:70px;height:46px;border-radius:8px;display:grid;place-items:center;font:10px monospace;color:#fff;text-shadow:0 1px 2px #0008}", j: "" } },
      flow: ["Pick color format", "Pick unit per job", "text: rem", "layout: %/fr"],
      task: "Build a palette of 5 swatches (one each: named, hex, rgb, rgba, color-mix). Then size one swatch with 50vw and another with 200px — resize the window and watch which one moves.",
      mistake: "Using px for body text (it never scales with the user's browser font-size setting) or % for padding (it's relative to the containing block's WIDTH, not height — a classic surprise). Text in rem, layout in % or fr.",
      tip: "Define your palette once as CSS variables at the top of the file (--gold: #F5B23D;) and reference them everywhere. A rebrand becomes a one-line edit instead of a find-and-replace across the site.",
      challenge: "A button is width: 100px in a container that's 300px wide. Now the container becomes 200px, then the user zooms the browser to 200%. What happens to the button in each case, and which unit would make it 'fill half the container' instead?" },

    { t: "Fonts and typography: making text feel designed",
      text: "Typography is 90% of how a page feels. The core properties: font-family (always end with a generic fallback — sans-serif, serif, monospace), font-size (rem for text), font-weight (400 normal, 700 bold), line-height (1.5–1.7 for readable body text), and letter-spacing. For web fonts, load them in <head> and set font-display: swap so text shows immediately while the font downloads.",
      def: "Typography properties (font-family, size, weight, line-height, letter-spacing) control how text reads; web fonts load via <link> with a fallback stack.",
      code: "body {\n  font-family: Georgia, serif;\n  font-size: 1rem;        /* 16px */\n  line-height: 1.6;       /* readable */\n  color: #20232b;\n}\n\nh1 {\n  font-family: 'Fraunces', serif;\n  font-size: 2.4rem;\n  font-weight: 600;\n  letter-spacing: -0.01em;\n}\n\nfont-family list = preference order.\nAlways end with a generic fallback.",
      out: { web: { h: "<h1>Georgia, serif</h1><p>Body at 1rem with line-height 1.6 — the most common readable setting on the web.</p><h2 style=\"font-family:'Courier New',monospace;letter-spacing:.02em\">Monospace, 1.4rem</h2><p style=\"line-height:2.2;font-size:1.2rem\">This paragraph has line-height 2.2 and 1.2rem — notice how much airier it feels.</p>", c: "body{font-family:Georgia,serif;font-size:16px;line-height:1.6;color:#20232b;background:#faf7f0;padding:24px;margin:0} h1{font-size:2.4rem;font-weight:600;letter-spacing:-.01em;color:#b3543c} h2{font-size:1.4rem;color:#3a5fa0}", j: "" } },
      flow: ["family + fallback", "size in rem", "line-height 1.5–1.7", "weight + spacing"],
      task: "Set up a page with a serif heading (2.2rem, 600) and sans-serif body (1rem, line-height 1.7). Then bump line-height to 2.5 — how does readability change? Pick the better value.",
      mistake: "A font-family with no generic fallback (if the web font fails, the browser picks an arbitrary default) or line-height: 1 on body text (lines touch, and it's tiring). Fallbacks always; body line-height at least 1.5.",
      tip: "Pair at most two typefaces per site (one for headings, one for body) and a monospace for code. More than that starts to look like a template fair — MeenLearn itself uses exactly three, for a reason.",
      challenge: "A web font makes text 'jump' on load (visible text swaps to a different one mid-page). What CSS property on the @font-face fixes the timing, and what's the trade-off of its 'swap' value?" },

    { t: "The box model: content, padding, border, margin",
      text: "Every element is a box with four layers: content (the stuff), padding (space inside the border), border (the line), and margin (space outside, between boxes). The total width you see = content + padding + border + margin. The one global rule that makes layout sane: * { box-sizing: border-box } — it makes width include padding and border, so the math finally matches what you see. This is the most important concept in CSS; learn it until it's automatic.",
      def: "The box model: every element is content + padding + border + margin; width/height refer to the content box unless box-sizing: border-box is set.",
      code: "     MARGIN\n   +--------------+\n   |  BORDER      |\n   | +----------+ |\n   | | PADDING  | |\n   | |+--------+| |\n   | ||CONTENT || |\n   | |+--------+| |\n   | +----------+ |\n   +--------------+\n\nwidth = content + padding + border\n(unless border-box: then width is\nthe whole thing incl. padding+border)",
      out: { web: { h: "<div class=\"box\" style=\"margin:14px\"><span>content: 150px</span></div><p>Same box, padding 30, border 4, margin 14. Total footprint: 150 + 60 + 8 + 28 = 246px wide.</p>", c: "body{font-family:sans-serif;background:#faf7f0;padding:24px;color:#222;margin:0} .box{width:150px;height:80px;background:#F5B23D;border:4px solid #14171f;padding:30px;margin:14px;font:11px monospace;color:#241a08} p{font-size:13px;color:#555}", j: "" } },
      flow: ["content", "+ padding (inside)", "+ border", "+ margin (outside)", "box-sizing: border-box!"],
      task: "Build three boxes: each 200px wide, with different padding/border/margin. Calculate each one's total footprint on paper, then measure in DevTools (the Elements panel shows the box layers colored). Do your numbers match?",
      mistake: "A box that's 'too wide' and overflows the page: you set width: 100% and then added padding, and the total became 100% + padding. The fix is the global rule html * { box-sizing: border-box } — put it at the top of every stylesheet and never think about it again.",
      tip: "In DevTools, the Elements panel draws the box model around any selected element (blue = margin, green = border, yellow = padding, pink = content). Hover the layers to see exact values — this skill pays for itself in week one.",
      challenge: "Two boxes in a row: each width: 50%, padding: 10px, box-sizing default. Why do they wrap to two lines instead of sitting side by side? What's the one-line global fix, and what's the per-box fix?" },

    { t: "Margins and the collapsing mystery",
      text: "Margin is the space outside a box — but vertical margins between block siblings collapse: if one has margin-bottom: 20px and the next has margin-top: 30px, the gap is 30px, not 50px (the larger wins). This trips up everyone once. The modern answer: stop using margins for spacing between items — use a flex/grid container with gap, and reserve margins for outer spacing (a section's margin-top).",
      def: "Margin is outer spacing; vertical margins of adjacent block boxes collapse to the larger of the two instead of adding.",
      code: "A { margin-bottom: 20px }\nB { margin-top: 30px }\n\nA then B:\n  gap = max(20, 30) = 30px\n  NOT 50. They collapse.\n\nFix: don't fight it.\nParent:  display: flex;\n         flex-direction: column;\n         gap: 20px;\nChildren: no margins. Done.",
      out: { web: { h: "<p class=\"a\">Box A (margin-bottom: 20px)</p><p class=\"b\">Box B (margin-top: 30px)</p><p style=\"font-size:12px;color:#888\">The gap above is 30px, not 50px — margins collapsed. Now the flex+gap version:</p><div class=\"stack\"><span>A</span><span>B</span></div>", c: "body{font-family:sans-serif;background:#faf7f0;padding:24px;color:#222;margin:0} .a{background:#eef3fb;padding:14px;border:1px solid #5E8CE6;margin-bottom:20px;border-radius:6px} .b{background:#fdeee9;padding:14px;border:1px solid #E2664F;margin-top:30px;border-radius:6px} .stack{display:flex;flex-direction:column;gap:20px} .stack span{padding:14px;border-radius:6px;font-weight:bold} .stack span:first-child{background:#eef3fb} .stack span:last-child{background:#fdeee9}", j: "" } },
      flow: ["margins = outer space", "vertical siblings collapse", "larger margin wins", "prefer gap over margins"],
      task: "Recreate the collapsing demo: two boxes with 20px bottom / 30px top margins. Measure the real gap. Then wrap them in a flex column with gap: 20px and remove the margins — is the spacing now predictable?",
      mistake: "Adding margin-bottom to every child in a list to space them — then the last child carries a stray margin into the next section (the 'extra space at the bottom' bug). gap or margin-top on children (not bottom) avoids it entirely.",
      tip: "A useful mental upgrade: think of spacing as belonging to the container (gap) rather than the children (margins). It's the same reason modern layout tutorials reach for flex/grid gap first.",
      challenge: "A card has margin: 20px and sits inside a parent with overflow: hidden. The parent looks 'cut off' on the top. What's happening (hint: margin collapsing through the parent's edge), and what's the standard fix (hint: a small padding or border on the parent)?" },

    { t: "display: block, inline, and turning things off",
      text: "display controls how an element participates in layout. The common values: block (own line, full width — p, div), inline (flows in text — span, a), inline-block (inline flow but can have width/height), none (removed entirely — gone AND its space), flex and grid (the two real layout systems, next lessons). Toggling display: none with JavaScript is the classic way to show/hide UI.",
      def: "display sets an element's layout behavior: block, inline, inline-block, none, flex, grid — changing how it flows, sizes, and whether it exists in the layout at all.",
      code: "p, div   -> display: block\nspan, a  -> display: inline\n\ninline:  no width/height,\n         no top/bottom margin\ninline-block: in text, BUT\n         width/height work\nnone:     removed from layout\n         (no space left behind)\n\nJS show/hide:\nel.style.display = 'none'   /* hide */\nel.style.display = ''       /* back */",
      out: { web: { h: "<p>This has <span class=\"in\">an inline span</span> (no size) and <span class=\"ib\">an inline-block span</span> (it can be sized) and a <button class=\"hider\">hide me</button> that toggles a paragraph.</p><p id=\"victim\">This paragraph will be display:none. Note: no gap remains where it was.</p>", c: "body{font-family:sans-serif;background:#faf7f0;padding:24px;color:#222;margin:0} .in{background:#f5b23d55;padding:2px} .ib{background:#5E8CE655;padding:2px 10px;display:inline-block;width:90px} .hider{padding:6px 10px;border:1px solid #ccc;border-radius:6px;cursor:pointer} #victim{background:#eef3fb;padding:12px;border-radius:6px}", j: "document.querySelector('.hider').addEventListener('click',function(){var v=document.getElementById('victim');v.style.display = v.style.display==='none' ? '' : 'none';});" } },
      flow: ["default per element", "block / inline / inline-block", "none = removed", "JS toggles it"],
      task: "Make a button that hides and shows a paragraph (toggle display between '' and 'none'). Then swap the technique: use visibility: hidden instead — what's the difference in the space left behind?",
      mistake: "Setting width/height on an inline element and wondering why it's ignored (make it inline-block first), or using display: none on a parent without remembering it hides ALL children (no exceptions — that's usually the intent, but not always).",
      tip: "display: none vs visibility: hidden: the first removes the element AND its space (layout reflows); the second keeps the space (a blank hole). Use none for 'this shouldn't be here', hidden for 'keep the spot, hide the content'.",
      challenge: "You need a widget that can be hidden, but when hidden it must leave its space (other content shouldn't shift). Which property do you use, and why can't display: none do this job?" },

    { t: "position: placing things with precision",
      text: "position controls where an element sits in layout. The five values: static (default, normal flow), relative (offset from its own spot — and the anchor for absolute children), absolute (removed from flow, placed relative to the nearest positioned ancestor), fixed (stays put while the page scrolls), sticky (in flow until a scroll threshold, then sticks). The #1 beginner bug: absolute does nothing because no ancestor is positioned — set the parent to relative first.",
      def: "position sets layout mode: static (default), relative (offset anchor), absolute (out of flow, anchored to positioned ancestor), fixed (viewport-locked), sticky (scroll-then-stick).",
      code: "static    normal flow (default)\nrelative  offset from own spot;\n          the anchor for absolute\nabsolute  out of flow; placed vs\n          nearest POSITIONED ancestor\nfixed     locked to the viewport\nsticky    in flow until threshold,\n          then sticks\n\nTHE FIX for 'absolute is ignored':\nparent { position: relative }\nchild  { position: absolute\n         top: 0; right: 0 }",
      out: { web: { h: "<div class=\"wrap\"><span class=\"badge\">absolute badge, parent is relative</span>Normal flow text. The badge floats out of the flow, anchored to the wrapper's top-right corner. Scroll the page: the badge stays with the box (not the viewport) — that's absolute, not fixed.</div>", c: "body{font-family:sans-serif;background:#faf7f0;padding:24px;color:#222;margin:0} .wrap{position:relative;background:#eef3fb;border:1px solid #5E8CE6;padding:24px;border-radius:8px;min-height:120px} .badge{position:absolute;top:8px;right:8px;background:#f5b23d;color:#241a08;font:11px monospace;padding:4px 8px;border-radius:4px} p.filler{height:600px;color:#999;font-size:12px}", j: "var p=document.createElement('p');p.className='filler';p.textContent='Filler so you can scroll and see the badge does NOT stick to the viewport.';document.body.appendChild(p);" } },
      flow: ["static (default)", "relative = anchor", "absolute = out of flow", "fixed = viewport", "sticky = scroll-stick"],
      task: "Build a card with a 'NEW' badge pinned to its top-right: the card is position: relative, the badge absolute. Then change the badge to fixed and scroll — what's the difference in behavior?",
      mistake: "position: absolute with no positioned ancestor — the element anchors to the page (or the initial containing block) and ends up somewhere baffling. The fix is always: position: relative on the intended parent.",
      tip: "Sticky is the modern replacement for the old 'fixed header with manual offsets' hack: position: sticky; top: 0 on a nav makes it stick on scroll with zero JavaScript. It only works if no ancestor has overflow: hidden/auto (a common silent killer).",
      challenge: "A toolbar is position: sticky; top: 0 inside a container that has overflow: auto. It doesn't stick. Why, and what are two ways to fix it (one structural, one CSS)?" },

    { t: "z-index and stacking order",
      text: "When positioned elements overlap, z-index decides who paints on top: higher number in front, negative behind. It only works on positioned elements (position != static) or flex/grid items — that's why 'I set z-index and nothing changed' is usually 'this element isn't positioned'. Start small (1, 2, 10, and 100 for modals) instead of 9999 — the large numbers pile up and eventually collide.",
      def: "z-index sets the stacking order of overlapping positioned elements: higher paints in front; it applies only to positioned (or flex/grid) elements.",
      code: ".card-a { position: relative; z-index: 1 }\n.card-b { position: relative; z-index: 2 }\n/* b paints in front of a */\n\nRules:\n- needs position (or flex/grid item)\n- default is auto (0-ish)\n- negative goes BEHIND\n- scale: 1, 2, 10, 100 (modals)\n\nOverlapping but no z-index works?\nCheck: are BOTH positioned?",
      out: { web: { h: "<div class=\"stage\"><div class=\"box a\">z-index: 1</div><div class=\"box b\">z-index: 2</div><div class=\"box c\">z-index: -1 (behind)</div></div><p style=\"font-size:12px;color:#777\">Three positioned boxes overlap. b is in front of a; c hides behind both.</p>", c: "body{font-family:sans-serif;background:#faf7f0;padding:24px;color:#222;margin:0} .stage{position:relative;height:140px} .box{position:absolute;width:120px;height:70px;display:grid;place-items:center;font:12px monospace;border-radius:8px} .a{top:20px;left:0;background:#5E8CE6;z-index:1} .b{top:45px;left:80px;background:#E2664F;z-index:2} .c{top:0;left:180px;background:#999;z-index:-1} .c::after{content:''}", j: "" } },
      flow: ["overlap happens", "both positioned?", "higher z = front", "keep numbers small"],
      task: "Stack three boxes with z-index 1, 2, -1 so they overlap visibly. Then set one to position: static — what happens to its z-index, and why?",
      mistake: "Bumping to z-index: 9999, then 99999 when it 'doesn't work' — the real problem is almost always that the element (or its parent) isn't positioned, or a parent with its own stacking context is capping it. Diagnose before escalating numbers.",
      tip: "A 'stacking context' is created by positioned elements with z-index set, and by opacity < 1, transforms, and filters. Children can't escape their context's z-order — which is why a '99999' child can still hide behind a sibling. When z-fighting gets weird, look one level up.",
      challenge: "A dropdown (z-index: 50) hides behind a card (z-index: 10) in the same section, even though 50 > 10. The dropdown is inside a parent with opacity: 0.95. Explain what's happening and the fix." },

    { t: "Flexbox: laying out in one direction",
      text: "Flexbox arranges items in a single direction — a row or a column. Set display: flex on the parent, then steer with: flex-direction (row/column), justify-content (main-axis alignment), align-items (cross-axis), gap (spacing), and flex-wrap (allow wrapping). On items: flex: 1 to grow into available space. It's the default choice for toolbars, card rows, centering, and navigation.",
      def: "Flexbox is a one-dimensional layout: the parent (display: flex) controls a main axis (justify-content), a cross axis (align-items), gaps, wrapping, and per-item growth (flex).",
      code: ".row {\n  display: flex;\n  gap: 12px;\n  justify-content: space-between; /* main */\n  align-items: center;            /* cross */\n}\n\n.item { flex: 1 }   /* grow to fill */\n\nThe two axes:\n  row:    main = horizontal\n  column: main = vertical\n\nCentering anything, forever:\ndisplay:flex;justify-content:center;\nalign-items:center;",
      out: { web: { h: "<div class=\"toolbar\"><span class=\"t\">Logo</span><span class=\"t grow\">grows (flex: 1)</span><span class=\"t\">Search</span><span class=\"t\">Menu</span></div><p style=\"font-size:12px;color:#777;margin-top:12px\">One flex row, gap 10px, the middle item grows with flex:1.</p>", c: "body{font-family:sans-serif;background:#faf7f0;padding:24px;color:#222;margin:0} .toolbar{display:flex;gap:10px;align-items:center;background:#14171f;border-radius:10px;padding:10px} .t{background:#232838;color:#eceae3;padding:10px 14px;border-radius:6px;font-size:13px} .grow{flex:1;text-align:center;color:#f5b23d}", j: "" } },
      flow: ["display: flex", "pick a main axis", "justify (main)", "align (cross) + gap", "flex:1 to grow"],
      task: "Build a toolbar: logo, a growing search box (flex: 1), and two buttons, using one flex row with gap. Then flip it to flex-direction: column and watch which property now controls 'main axis' alignment.",
      mistake: "Fighting flexbox with margins: adding margin-left to items to space them (use gap instead) or expecting an item to break to a new line (add flex-wrap: wrap first). Flexbox does spacing and wrapping for you — stop hand-placing.",
      tip: "The eternal centering trick, memorize it: display: flex; justify-content: center; align-items: center. It centers one child (or a group) both ways, at any size. Half of all CSS Stack Overflow questions of the last decade answered by these three lines.",
      challenge: "A flex row has three items and justify-content: space-between, but the items all hug the left edge. What's missing (hint: the items' own sizing), and why does adding flex: 1 to one item change the distribution?" },

    { t: "Flexbox: alignment, wrapping, and the fine controls",
      text: "The second half of flexbox: align-items aligns every item on the cross axis; align-self overrides it for one item; flex-wrap: wrap lets items break to new lines; and the item properties flex-grow / flex-shrink / flex-basis fine-tune how space is divided. The shorthand flex: 1 1 0 is the common 'grow to share equally' — it's what makes rows of cards equal-width without measuring anything.",
      def: "Flexbox item controls: align-self (per-item cross alignment), flex-wrap (line breaks), and flex-grow/shrink/basis (how space divides among items).",
      code: ".cards {\n  display: flex;\n  flex-wrap: wrap;     /* allow new lines */\n  gap: 12px;\n}\n.card {\n  flex: 1 1 200px;\n  /* grow 1, shrink 1, basis 200px */\n  /* = 'at least 200, share the rest' */\n}\n\nalign-items: stretch  (default, equal height)\nalign-self: start     (one item, its own)\n\nEqual-height cards: flex + stretch,\nno hacks.",
      out: { web: { h: "<div class=\"cards\"><div class=\"card\">Short</div><div class=\"card\">This card has much longer text that wraps onto several lines to prove the others stretch to match its height.</div><div class=\"card\">Ok</div></div>", c: "body{font-family:sans-serif;background:#faf7f0;padding:24px;color:#222;margin:0} .cards{display:flex;flex-wrap:wrap;gap:12px} .card{flex:1 1 140px;background:#eef3fb;border:1px solid #5E8CE6;border-radius:8px;padding:14px;font-size:13px}", j: "" } },
      flow: ["wrap allowed", "basis sets a floor", "grow shares extra", "stretch equalizes height"],
      task: "Build a responsive card row: flex-wrap, each card flex: 1 1 200px. Resize the window from wide to narrow — the cards reflow without any media query. What's the 'break point' in pixels where they wrap?",
      mistake: "Expecting flex items to be equal-width and they're not (they size to content by default — add flex: 1 or a basis) or using align-items: center on a row of cards and getting ragged bottom edges (the default stretch is what keeps card heights equal).",
      tip: "flex: 1 1 200px is a workhorse: 'start at 200px, grow to share extra space, shrink if squeezed'. It turns a card row into a free auto-layout that adapts to any container — no measurements, no media queries.",
      challenge: "Two items: one flex: 1, one flex: 2, in a 600px container with a 12px gap. What's each item's width? (Show the math: subtract the gap first, then split 1:2.)" },

    { t: "CSS Grid: laying out in two dimensions",
      text: "Grid is the two-dimensional layout system: it controls rows AND columns at once. The minimum: display: grid on the parent, grid-template-columns: repeat(3, 1fr) for three equal columns, and gap for spacing — children flow into cells automatically. Span items across cells with grid-column: span 2. The division of labor: grid for page-level and gallery layouts, flexbox for one-dimensional rows inside components.",
      def: "CSS Grid is a 2D layout system: the parent defines columns and rows (grid-template-*, gap); children place into cells and can span multiple rows or columns.",
      code: ".gallery {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 12px;\n}\n\n.cell { ... }\n.wide { grid-column: span 2; }\n\n1fr = one share of free space.\nrepeat(3, 1fr) = 3 equal columns.\n\nAuto-rows: children create rows as\nneeded. No table of cells to plan.",
      out: { web: { h: "<div class=\"g\"><div class=\"c\">1</div><div class=\"c wide\">2 (spans 2)</div><div class=\"c\">3</div><div class=\"c\">4</div><div class=\"c\">5</div><div class=\"c\">6</div></div>", c: "body{font-family:sans-serif;background:#faf7f0;padding:24px;color:#222;margin:0} .g{display:grid;grid-template-columns:repeat(3,1fr);gap:10px} .c{background:#5E8CE622;border:1px solid #5E8CE6;border-radius:8px;padding:18px 10px;text-align:center;font-weight:bold} .wide{background:#f5b23d44;border-color:#f5b23d}", j: "" } },
      flow: ["display: grid", "define columns", "gap", "items auto-flow", "span to merge cells"],
      task: "Build a gallery: 6 cells, 3 columns, one cell spanning 2 columns. Then change to repeat(auto-fill, minmax(140px, 1fr)) — what happens as you resize the window?",
      mistake: "Using grid for a simple toolbar of buttons (flexbox is lighter and the right tool) or using floats/absolute positioning to build a page when grid does it in 4 lines. Pick the system by dimension: one direction = flex, two = grid.",
      tip: "repeat(auto-fill, minmax(200px, 1fr)) is the famous responsive gallery: 'as many 200px-min columns as fit, each stretching to fill'. It replaces most media queries for card layouts — try it and see.",
      challenge: "In a 3-column grid, item 4 has grid-column: 2 / 4. What does '2 / 4' mean (hint: line numbers, not columns), and which cells does it actually cover?" },

    { t: "Grid: templates, areas, and named lines",
      text: "The power level of grid: define named areas and assign them to children, and the layout reads like a diagram. grid-template-areas: \"header header\" \"sidebar main\" makes the structure visible in the CSS itself. Named lines (grid-column: start / end) let you place items by line instead of counting. This is what makes page skeletons maintainable — the layout is a picture in your stylesheet.",
      def: "Grid templates use grid-template-areas (a visual map of named regions) and named lines to place items declaratively — the page layout as a diagram in CSS.",
      code: ".page {\n  display: grid;\n  grid-template-columns: 220px 1fr;\n  grid-template-rows: auto 1fr auto;\n  grid-template-areas:\n    \"header header\"\n    \"side   main\"\n    \"footer footer\";\n  gap: 14px;\n}\n\n.page > header { grid-area: header }\n.page > aside  { grid-area: side }\n.page > main   { grid-area: main }\n.page > footer { grid-area: footer }\n\nThe CSS IS the wireframe.",
      out: { web: { h: "<div class=\"page\"><header>HDR</header><aside>SIDE</aside><main>MAIN (takes the rest)</main><footer>FTR</footer></div>", c: "body{font-family:sans-serif;background:#faf7f0;padding:24px;margin:0;color:#222} .page{display:grid;grid-template-columns:110px 1fr;grid-template-rows:auto 1fr auto;grid-template-areas:\"header header\" \"side main\" \"footer footer\";gap:10px;height:220px} .page>*{border-radius:8px;display:grid;place-items:center;font-weight:bold;font-size:12px} header{grid-area:header;background:#14171f;color:#f5b23d} aside{grid-area:side;background:#5E8CE633;border:1px solid #5E8CE6} main{grid-area:main;background:#f5b23d22;border:1px solid #f5b23d} footer{grid-area:footer;background:#eee;color:#666}", j: "" } },
      flow: ["define areas map", "name the regions", "assign grid-area", "layout = diagram"],
      task: "Rebuild the page skeleton above from memory (header spanning, sidebar, main, footer). Then swap the sidebar to the right side — how many lines of CSS change? (Answer: one, in the areas string.)",
      mistake: "Counting cell numbers to place items (grid-column: 3) and having everything break when you add a column — named lines and areas keep placement stable when the template changes.",
      tip: "When a layout change used to mean touching six rules, write the template-areas string first: the 'new wireframe' in one place, and the rest of the CSS just assigns regions. It's the difference between a layout and a plan.",
      challenge: "Add a 'featured' row between header and the side/main row in the template. Rewrite grid-template-areas and the row sizes — which children's CSS must change, and which need nothing at all?" },

    { t: "Responsive design and media queries",
      text: "Responsive design means the page adapts to screen size. The modern approach is mobile-first: write base styles for small screens, then @media (min-width: 768px) { ... } adds layout as space appears. Breakpoints are where your layout actually breaks — common stops at 640, 768 and 1024px. Also make images fluid (max-width: 100%) and avoid fixed pixel widths. Test by resizing the window (or DevTools device mode).",
      def: "Responsive design adapts layout to viewport size, typically mobile-first: base styles for small screens, @media (min-width: ...) blocks that add complexity as space appears.",
      code: "/* base = mobile */\n.cards { display: grid; gap: 12px; }\n\n/* tablet and up */\n@media (min-width: 640px) {\n  .cards { grid-template-columns: repeat(2, 1fr); }\n}\n\n/* desktop */\n@media (min-width: 1024px) {\n  .cards { grid-template-columns: repeat(3, 1fr); }\n}\n\nMobile first: start small, add up.\nBreakpoint = where YOUR layout\nbreaks, not a magic number.",
      out: { web: { h: "<div class=\"cards\"><div class=\"card\">A</div><div class=\"card\">B</div><div class=\"card\">C</div><div class=\"card\">D</div><div class=\"card\">E</div><div class=\"card\">F</div></div><p class=\"hint\">Resize the preview (or your window). 1 column now, 2 above 640px, 3 above 1024px — same HTML, zero JS.</p>", c: "body{font-family:sans-serif;background:#faf7f0;padding:24px;margin:0;color:#222} .cards{display:grid;gap:10px} .card{background:#eef3fb;border:1px solid #5E8CE6;border-radius:8px;padding:20px;text-align:center;font-weight:bold} @media(min-width:640px){.cards{grid-template-columns:repeat(2,1fr)}} @media(min-width:1024px){.cards{grid-template-columns:repeat(3,1fr)}} .hint{font-size:12px;color:#888}", j: "" } },
      flow: ["mobile-first base", "@media min-width", "add columns/spacing", "test by resizing"],
      task: "Build a card grid that's 1 column on mobile, 2 on tablet, 3 on desktop (the example above). Resize across each breakpoint and confirm the transitions. Where exactly do the changes happen, in pixels?",
      mistake: "Desktop-first media queries (max-width) — you write the big layout then subtract features, which is backwards and bug-prone. And fixed pixel widths (width: 1200px) that ignore the viewport. Start small, add up, and let % / fr / auto-fill do the adapting.",
      tip: "DevTools device mode (toggle the device icon in the Elements panel) lets you preview iPhone/Android/tablet widths without a device. Test the real breakpoints — 375px (small phone) is where most layouts first break.",
      challenge: "A site looks perfect at 1440px but at 800px the sidebar overlaps the main content. It was built desktop-first with max-width queries. What's the structural problem, and what's the mobile-first rewrite in a few lines?" },

    { t: "Responsive units: %, rem, vh/vw, and clamp()",
      text: "The unit toolkit for fluid layouts: % (of the parent), rem (of the root font — for text), vw/vh (of the viewport: 100vh = full screen height), and fr (grid fractions). The modern star is clamp(): a value with a min, a preferred (fluid) value, and a max — clamp(1rem, 2.5vw, 1.6rem) scales the text with the viewport but never below 1rem or above 1.6rem. Fluid type with no media queries.",
      def: "Fluid units: % (parent-relative), rem (root-font-relative), vw/vh (viewport-relative), fr (grid), and clamp(min, preferred, max) for values that scale with bounds.",
      code: "width: 90%;          /* of parent */\nfont-size: 1.25rem;  /* of root (16px) */\nheight: 100vh;       /* full viewport */\nwidth: 50vw;         /* half viewport */\ngrid: ... 2fr 1fr;   /* fractions */\n\nFluid headline, no media query:\nfont-size: clamp(1.8rem, 4vw, 3rem);\n/* min 1.8rem, wants 4vw, max 3rem */\n\nText: rem. Layout: % or fr.\nBig type: clamp.",
      out: { web: { h: "<h1 class=\"fluid\">Fluid headline</h1><p>Resize the window: the heading scales with the viewport (4vw) but clamps between 1.6rem and 2.8rem. No media queries.</p><p class=\"vp\">This block is 60vh tall — 60% of your viewport height.</p>", c: "body{font-family:Georgia,serif;background:#14171f;color:#eceae3;padding:24px;margin:0} .fluid{font-size:clamp(1.6rem,4vw,2.8rem);color:#f5b23d;margin:0 0 10px} p{color:#8b92a3;line-height:1.6} .vp{height:60vh;min-height:120px;background:#232838;border-radius:10px;display:grid;place-items:center;font-size:13px}", j: "" } },
      flow: ["% = parent", "rem = root font", "vw/vh = viewport", "fr = grid", "clamp = fluid w/ bounds"],
      task: "Make a hero headline with clamp() (min 1.5rem, preferred 5vw, max 3.5rem). Resize the window and note where it stops scaling (the clamp kicking in). What viewport widths trigger each bound?",
      mistake: "100vh on mobile — it's wrong because mobile URL bars change the visible height (the page 'scrolls' with nothing there). For full-viewport sections, 100svh (small viewport height) or dvh is the modern fix; at minimum, know the issue exists.",
      tip: "A clean system: text in rem (scales with user preference), layout in % / fr, full-screen moments in dvh, and clamp for anything that should feel fluid. That four-part division covers 95% of real responsive work.",
      challenge: "Why is font-size: 2em different from font-size: 2rem when the parent has font-size: 20px? (Show both calculations.) Which one is 'the root setting', and why does that make it the safer default?" },

    { t: "Transitions: making change feel smooth",
      text: "A transition animates a property change over time: .card { transition: transform .2s ease; } and .card:hover { transform: translateY(-4px); } — the lift eases in instead of teleporting. Rules: list the properties you want to animate (transition: all is convenient but animates things you didn't ask for, and it's slower), keep duration 0.15–0.3s for snappy UI, and use ease / ease-out curves. Transitions are how hover effects stop feeling robotic.",
      def: "A transition defines how (duration, timing curve) an element animates between two states when a listed property changes — the standard tool for hover and focus effects.",
      code: ".card {\n  transition: transform .2s ease-out,\n              box-shadow .2s ease-out;\n}\n.card:hover {\n  transform: translateY(-4px);\n  box-shadow: 0 12px 24px #0003;\n}\n\nOnly LISTED properties animate.\n0.15-0.3s = snappy. ease-out feels\nnatural (fast start, soft landing).\n\nNo JS. Just two rules.",
      out: { web: { h: "<div class=\"card\">Hover me</div><p style=\"font-size:12px;color:#888;margin-top:14px\">The lift and shadow ease over 0.2s — transition on the base rule, the new values on :hover.</p>", c: "body{font-family:sans-serif;background:#faf7f0;padding:24px;color:#222;margin:0;display:grid;place-items:center;min-height:80vh} .card{width:220px;height:130px;background:#14171f;color:#f5b23d;display:grid;place-items:center;font-weight:bold;border-radius:14px;transition:transform .2s ease-out, box-shadow .2s ease-out;cursor:pointer} .card:hover{transform:translateY(-6px);box-shadow:0 16px 30px #0004}", j: "" } },
      flow: ["base: transition", "state: new values", "property changes", "browser animates it"],
      task: "Build a button that eases its background, transform, and shadow on hover (0.2s ease-out). Then set transition: all .5s — what changed about the feel, and what might animate that you didn't want?",
      mistake: "transition: all on a big component — it animates layout properties on resize and scroll, causing jank, and it's a performance smell. List the specific properties (transform, opacity, box-shadow are the cheap, smooth ones).",
      tip: "Animate transform and opacity first — they're GPU-composited (smooth). Animating width, height, or top is a layout animation (re-paints every frame, can jank). If you need a size change, consider scaling a fixed-size element instead.",
      challenge: "A modal appears, but the opacity jumps from 0 to 1 instantly even though the CSS says transition: opacity .3s. What's the classic cause (hint: when did the element enter the DOM / get its class), and the two standard fixes?" },

    { t: "Animations: @keyframes and looping motion",
      text: "For motion that runs on its own (floating shapes, pulsing dots, spinners), @keyframes defines the frames and animation applies them: @keyframes float { 50% { transform: translateY(-10px); } } with .ball { animation: float 3s ease-in-out infinite; }. You can define any percentage stops, not just 0/100. Use keyframes for repeating and autonomous motion; use transitions for reacting to user actions.",
      def: "@keyframes defines the frames of an animation (any % stops); the animation property applies it with a duration, curve, and iteration count (infinite loops).",
      code: "@keyframes float {\n  0%, 100% { transform: translateY(0); }\n  50%      { transform: translateY(-12px); }\n}\n\n.ball { animation: float 3s ease-in-out infinite; }\n\n@keyframes pulse {\n  0%   { transform: scale(1);   opacity: 1 }\n  100% { transform: scale(1.6); opacity: 0 }\n}\n.ring { animation: pulse 1.6s ease-out infinite; }\n\nAny % stops. infinite loops.\ndelay, count, fill-mode all tune it.",
      out: { web: { h: "<div class=\"scene\"><span class=\"dot\"></span><span class=\"ring\"></span></div><p style=\"font-size:12px;color:#888;text-align:center\">A floating dot and a pulsing ring — pure @keyframes, no JS.</p>", c: "body{font-family:sans-serif;background:#14171f;color:#eceae3;padding:24px;margin:0} .scene{display:grid;place-items:center;height:180px} .dot{width:26px;height:26px;border-radius:50%;background:#f5b23d;animation:float 3s ease-in-out infinite} .ring{position:absolute;width:26px;height:26px;border-radius:50%;border:2px solid #6fc3b0;animation:pulse 1.6s ease-out infinite} @keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-14px)}} @keyframes pulse{0%{transform:scale(1);opacity:.9}100%{transform:scale(2.2);opacity:0}} .scene{position:relative}", j: "" } },
      flow: ["@keyframes frames", "any % stops", "animation applies", "infinite loops it"],
      task: "Build the floating-dot + pulsing-ring demo. Add a third element that spins 360° forever (rotate in keyframes, linear timing). What's the difference between linear and ease-in-out on the spin?",
      mistake: "Using transition for autonomous looping motion (transitions only run when a value CHANGES — nothing changes on their own, so nothing loops). For anything that repeats without input, it's keyframes.",
      tip: "Respect prefers-reduced-motion: wrap decorative animations in @media (prefers-reduced-motion: no-preference) { ... } so users who disable motion in their OS get a calm page. It's a one-line accessibility win that most sites skip.",
      challenge: "A spinner uses @keyframes spin { to { transform: rotate(360deg) } } with animation: spin 1s linear infinite. What happens with linear vs ease-in-out on the same spin, and why is linear the right choice for a loader?" },

    { t: "Pseudo-classes and pseudo-elements",
      text: "Two families, one colon vs two. Pseudo-CLASSES (single :) target states of real elements: :hover, :focus, :active, :first-child, :last-child, :nth-child(2n) (every even). Pseudo-ELEMENTS (double ::) target virtual parts: ::before and ::add generated content without extra HTML (great for shapes, underlines, icons), plus ::selection and ::placeholder.",
      def: "Pseudo-classes (:hover, :focus, :nth-child) style states of elements; pseudo-elements (::before, ::after, ::selection) style or add virtual parts of an element.",
      code: "Pseudo-classes (one colon) = STATE\na:hover      { color: gold }\ninput:focus  { border-color: teal }\nli:nth-child(2n) { background: ... }\n\nPseudo-elements (two colons) = PARTS\n.card::before {\n  content: \"\";            /* required */\n  position: absolute; ...\n}\n::selection  { background: gold }\n::placeholder{ color: #888 }\n\ncontent is mandatory on ::before/::after\n(even if empty string).",
      out: { web: { h: "<ul class=\"stripes\"><li>1</li><li>2</li><li>3</li><li>4</li></ul><p><input class=\"ph\" placeholder=\"type here\"></p><p>Hover the list items; type in the box. <span class=\"hl\">Select this text</span> to see ::selection.</p>", c: "body{font-family:sans-serif;background:#faf7f0;padding:24px;color:#222;margin:0} .stripes{list-style:none;padding:0;margin:0 0 16px} .stripes li{padding:10px 14px;margin-bottom:6px;border-radius:6px;background:#eef3fb;transition:background .15s,transform .15s} .stripes li:nth-child(2n){background:#fdeee9} .stripes li:hover{transform:translateX(6px);background:#f5b23d44} .ph{padding:10px;border:1px solid #ccc;border-radius:6px;width:220px} .ph::placeholder{color:#999;font-style:italic} .ph:focus{outline:2px solid #6fc3b0;border-color:#6fc3b0} ::selection{background:#f5b23d;color:#241a08}", j: "" } },
      flow: [":state = pseudo-class", "::part = pseudo-element", "content on ::before/after", "states react, parts decorate"],
      task: "Build a list where every second item is shaded (:nth-child(2n)) and items shift right on hover (:hover). Add a styled ::placeholder and a custom ::selection color. Which are classes, which are elements?",
      mistake: "Forgetting content on ::before/::after (the pseudo-element doesn't render without it — even an empty string counts) or using a single colon for ::before in old habits (it still parses for compatibility, but :: is the standard form).",
      tip: "::before/::after are your free HTML: a decorative bar, an arrow, a badge, or an icon without adding a tag to the markup. One rule: keep them decorative (content: \"\" or aria-hidden) so screen readers don't announce empty cruft.",
      challenge: "You want a small \"NEW\" badge in the corner of a card without adding a <span> to the HTML. Write it with ::after (position it, give it content). What's the one property that's easy to forget?" },

    { t: "CSS variables: themes in one place",
      text: "CSS variables (custom properties) store values you can reuse: :root { --gold: #F5B23D; } and .btn { background: var(--gold); }. Define the palette at the top, reference it everywhere, and a rebrand is a one-line change. They're the mechanism behind dark/light themes: swap the variable values on body.light and the whole page re-skins with zero other changes — exactly how this site's theme toggle works.",
      def: "CSS custom properties (--name: value) store reusable values; var(--name) reads them. Reassigning a variable re-themes everything that uses it.",
      code: ":root {\n  --gold: #F5B23D;\n  --ink:  #14171f;\n  --text: #eceae3;\n}\n\n.btn   { background: var(--gold); }\nbody  { background: var(--ink); }\n\n/* theme swap = reassign vars */\nbody.light {\n  --ink:  #f3f1ea;\n  --text: #1d2026;\n}\n\nOne edit, whole site re-skinned.\nVariables inherit (set on a parent,\nuse in children).",
      out: { web: { h: "<p class=\"note\">This whole card is styled with CSS variables. The <b>flip</b> button swaps a single <code>data-theme</code> attribute — every color follows, because they all read var(--...).</p><button class=\"flip\" id=\"flip\">flip the theme</button>", c: ":root{--bg:#14171f;--fg:#eceae3;--acc:#f5b23d;--card:#1c212c} body{background:var(--bg);color:var(--fg);font-family:sans-serif;padding:24px;margin:0} .note{background:var(--card);padding:18px;border-radius:10px;border-left:4px solid var(--acc);line-height:1.6} code{color:var(--acc)} .flip{margin-top:14px;background:var(--acc);border:0;padding:10px 16px;border-radius:8px;font-weight:bold;cursor:pointer} body.alt{--bg:#f3f1ea;--fg:#1d2026;--card:#fff;--acc:#c98a1b}", j: "document.getElementById('flip').addEventListener('click',function(){document.body.classList.toggle('alt');});" } },
      flow: ["define in :root", "use with var()", "inherit down the tree", "reassign to re-theme"],
      task: "Style a mini card with four CSS variables (bg, text, accent, card). Add a button that toggles a class on <body> reassigning all four — watch the card re-skin instantly. Which single element did you actually change?",
      mistake: "Using variables for one-off values (defining --one-off: 12px for a single rule) — they're for shared, reusable tokens. And forgetting variables don't cascade like fonts: they inherit, so setting them on :root (or a wrapper) makes them available to descendants.",
      tip: "Treat your variables as a design token list: colors, spacing scale, radii, shadows. When a new component needs 'the accent color', it's var(--accent) — not a hex you have to hunt down. This is how the MeenLearn theme toggle works in one rule block.",
      challenge: "A variable --pad is set on :root to 16px, and a <div class=\"box\"> inside a section sets --pad: 8px. The .box's padding reads var(--pad). What value wins, and why? (Hint: inheritance vs redefinition.)" },

    { t: "Project: build a responsive card layout",
      text: "The CSS capstone: a polished, responsive page combining everything — a header (sticky, flex), a hero (fluid type with clamp), a card grid (auto-fill, equal-height cards with hover lift via transition), and a footer. It must look good at 375px, 768px and 1440px, use CSS variables for the palette, and include one looping @keyframes accent. Build it, resize it, ship it.",
      def: "A responsive layout project: sticky flex header, clamp() hero type, auto-fill card grid, transition hover states, a keyframes accent, and a CSS-variable palette — tested at three breakpoints.",
      code: "SPEC (your checklist):\n[ ] :root palette as CSS variables\n[ ] sticky header (flex, space-between)\n[ ] hero: clamp() headline\n[ ] cards: repeat(auto-fill,\n    minmax(220px, 1fr)), gap\n[ ] card hover: transform + shadow\n    (transition .2s)\n[ ] one @keyframes accent\n[ ] 375 / 768 / 1440 all clean\n[ ] no fixed pixel widths\n\nThe CSS track, applied.\nBuild, resize, done.",
      out: { web: { h: "<header><b>Meen<span>Learn</span></b><span class=\"nav\">Cards · Hover · Fluid</span></header><h1 class=\"hero\">Responsive cards, fluid type.</h1><div class=\"grid\"><div class=\"card\"><h3>Card one</h3><p>auto-fill minmax(220px, 1fr) — as many columns as fit.</p></div><div class=\"card hot\"><h3>Card two</h3><p>Hover: translateY + shadow, transition .2s ease-out.</p></div><div class=\"card\"><h3>Card three</h3><p>Resize the preview: columns appear and disappear without media queries.</p></div></div><span class=\"pulse-dot\" aria-hidden=\"true\"></span>", c: ":root{--bg:#faf7f0;--fg:#20232b;--acc:#f5b23d;--card:#fff;--line:#e5e0d5} *{box-sizing:border-box} body{margin:0;background:var(--bg);color:var(--fg);font-family:Georgia,serif} header{position:sticky;top:0;display:flex;justify-content:space-between;align-items:center;padding:12px 20px;background:#14171f;color:#fff;z-index:5} header b span{color:var(--acc)} .nav{font:12px sans-serif;color:#999} .hero{font-size:clamp(1.6rem,4vw,2.6rem);padding:28px 20px 8px;margin:0;color:#b3543c} .grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:14px;padding:16px 20px 40px} .card{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:18px;transition:transform .2s ease-out,box-shadow .2s ease-out} .card:hover{transform:translateY(-4px);box-shadow:0 14px 26px #0001} .card h3{margin:0 0 6px} .card p{margin:0;font:13px/1.5 sans-serif;color:#666} .hot{border-color:var(--acc)} .pulse-dot{position:fixed;bottom:16px;right:16px;width:10px;height:10px;border-radius:50%;background:var(--acc);animation:p 1.8s ease-out infinite} @keyframes p{0%{box-shadow:0 0 0 0 #f5b23d88}100%{box-shadow:0 0 0 12px #f5b23d00}}", j: "" } },
      flow: ["palette in :root", "sticky flex header", "clamp() hero", "auto-fill grid", "hover + keyframes", "test 3 widths"],
      task: "Build the layout from the spec. Then, for each of the three widths (375 / 768 / 1440), screenshot it and note which rule is responsible for the look at that width. Which parts used NO media query at all?",
      mistake: "Adding a media query for every small tweak instead of letting auto-fill / clamp / % do the work (you end up with six queries that fight each other). If a layout can be fluid, make it fluid; reserve queries for structural changes (sidebar appears, nav collapses).",
      tip: "Before adding any fixed width, ask: could this be % , fr, or minmax? A layout that survives an unknown screen size is the mark of the track — fixed pixels are a last resort, not the first tool.",
      challenge: "Extend the project: add a dark mode by reassigning the :root variables under a .dark class, toggled by a button. How many color values in the component rules did you have to change? (It should be zero — that's the test.)" }
  ],

  javascript: [
    { t: "What JavaScript is and where it runs",
      opt: ["vscode"],
      text: "JavaScript is the language of behavior on the web: it reacts to clicks, updates the page without reloading, validates forms, and talks to servers. It runs in every browser (and on servers via Node.js). HTML is structure, CSS is style, JavaScript is the part that responds. You'll write it in a <script> tag in <head> or at the end of <body>, or in a separate .js file linked with <script src=\"app.js\">.",
      def: "JavaScript is a general-purpose programming language that runs in the browser (and servers), giving web pages behavior: events, dynamic content, and data exchange.",
      code: "<!-- inline -->\n<script>\n  console.log(\"I run in the browser\");\n<\/script>\n\n<!-- or a file -->\n<script src=\"app.js\" defer><\/script>\n\nWhere it fits:\n  HTML  = structure (what)\n  CSS   = style     (how it looks)\n  JS    = behavior  (what happens)\n\nOpen DevTools -> Console:\ntype console.log(1+1). That's JS.",
      out: { web: { h: "<p>Click the button — JavaScript did it, no reload:</p><button id=\"go\" style=\"padding:10px 18px;border:0;border-radius:8px;background:#14171f;color:#f5b23d;font-weight:bold;cursor:pointer\">Click me</button><p id=\"out\" style=\"font-weight:bold;color:#2c8a63\"></p>", c: "body{font-family:sans-serif;background:#faf7f0;color:#222;padding:24px;margin:0}", j: "let n=0; document.getElementById('go').addEventListener('click',()=>{n++;document.getElementById('out').textContent='Clicked '+n+' time'+(n>1?'s':'')+'. The page never reloaded.';});" } },
      flow: ["HTML + CSS exist", "JS attaches to the page", "events happen", "JS updates the page"],
      task: "Open DevTools (F12) on any page, go to the Console, and type console.log(2 * 3) then 2 * 3 (without the log). What's the difference in what shows? That's your JS playground from now on.",
      mistake: "Placing a <script> that uses the DOM before the elements exist (the script runs top-to-bottom; a button defined below it isn't there yet). Fix: put scripts at the end of <body>, or use the defer attribute on file scripts.",
      tip: "console.log is your #1 tool and not a beginner crutch — professionals use it constantly. Console, Sources (breakpoints), and Elements are the three tabs that will answer 90% of your questions.",
      challenge: "A page has a <script> in <head> that references a <button> in <body>. The console says \"Cannot read properties of null\". Explain the order of events that caused it, and give two fixes." },

    { t: "Variables: const, let, and the var you'll avoid",
      text: "Use const by default — the name can't be reassigned, which prevents a whole class of bugs. Use let when the value must change (a counter). Avoid var — the old declaration, with confusing scoping rules that bite in loops and functions. One-line rule: const unless you have a reason for let, never var.",
      def: "const declares a name that can't be reassigned (the default); let declares one that can; var is the legacy declaration to avoid.",
      code: "const PI = 3.14;     // can't reassign\nlet score = 0;       // can change\nscore = 10;          // fine\nPI = 3.14159;        // ERROR: const\n\n// var: the old way\nvar old = 1;\n// function-scoped, hoisted,\n// redeclarable -> surprise bugs.\n\nHabit: const first.\nOnly let when it must change.",
      out: { web: { h: "<p><b>const</b> — locked:<br><code id=\"c\"></code></p><p><b>let</b> — changeable:<br><code id=\"l\"></code></p><button id=\"b\" style=\"padding:8px 14px;border:0;border-radius:6px;background:#14171f;color:#f5b23d;cursor:pointer\">increment let</button>", c: "body{font-family:sans-serif;background:#faf7f0;color:#222;padding:24px;margin:0} code{background:#14171f;color:#9fe8d8;padding:2px 6px;border-radius:4px;font-size:12px}", j: "const site='MeenLearn'; let clicks=0; document.getElementById('c').textContent='site = \"'+site+'\" (locked)'; const show=()=>document.getElementById('l').textContent='clicks = '+clicks; show(); document.getElementById('b').addEventListener('click',()=>{clicks++;show();});" } },
      flow: ["const = default", "let = must change", "var = avoid", "name points to a value"],
      task: "Write a counter: const start = 0 (hmm — that can't change; why?), so use let count = 0, then increment it three times and log each value. Where would const have been correct in this snippet?",
      mistake: "Using let for everything (you lose the reassignment protection and can't tell at a glance which values are meant to stay) or const for objects/arrays and then mutating the contents — const locks the NAME, not the contents: const list = []; list.push(1) is allowed (the variable still points to the same array).",
      tip: "A great litmus test: if you can't find where a variable is reassigned, it should be const. Grep for the name — if there's one assignment, make it const and let the code prove its intent.",
      challenge: "Why does this throw? const user = { name: \"Ada\" }; user.name = \"Moa\"; — (it doesn't!) But user = {} DOES throw. Explain the difference in one sentence, and why it matters when you 'copy' objects." },

    { t: "Data types and typeof (plus its two quirks)",
      text: "JavaScript types: string, number (integers and decimals are the same type), boolean, undefined (declared, no value), null (intentionally empty), object (including arrays), symbol, bigint. typeof tells you which — with two famous quirks: typeof null is \"object\" (a 30-year-old bug kept for compatibility), and typeof on an undeclared name throws. Check for undefined with typeof x === \"undefined\".",
      def: "JavaScript values have types (string, number, boolean, undefined, null, object...); typeof reports them, with the historic quirks around null and undeclared names.",
      code: "typeof \"hi\"     -> \"string\"\ntypeof 42       -> \"number\"\ntypeof 3.5      -> \"number\"\ntypeof true     -> \"boolean\"\ntypeof undefined-> \"undefined\"\ntypeof null     -> \"object\"  (quirk!)\ntypeof []       -> \"object\"  (arrays\n                              are objects)\n\nSafe undefined check:\ntypeof x === \"undefined\"\n(never: x === undefined if x\nmight not exist)",
      out: { web: { h: "<table style=\"border-collapse:collapse;font:13px monospace\"><tr><th style=\"text-align:left;padding:6px;border-bottom:2px solid #ccc\">value</th><th style=\"text-align:left;padding:6px;border-bottom:2px solid #ccc\">typeof</th></tr><tr><td style=\"padding:6px;border-bottom:1px solid #eee\">\"hi\"</td><td style=\"padding:6px;border-bottom:1px solid #eee\" id=\"a\"></td></tr><tr><td style=\"padding:6px;border-bottom:1px solid #eee\">42 / 3.5</td><td style=\"padding:6px;border-bottom:1px solid #eee\" id=\"b\"></td></tr><tr><td style=\"padding:6px;border-bottom:1px solid #eee\">true</td><td style=\"padding:6px;border-bottom:1px solid #eee\" id=\"c\"></td></tr><tr><td style=\"padding:6px;border-bottom:1px solid #eee\">null</td><td style=\"padding:6px;border-bottom:1px solid #eee\" id=\"d\"></td></tr><tr><td style=\"padding:6px\">[1,2,3]</td><td style=\"padding:6px\" id=\"e\"></td></tr></table>", c: "body{font-family:sans-serif;background:#faf7f0;color:#222;padding:24px;margin:0}", j: "document.getElementById('a').textContent=typeof \"hi\"; document.getElementById('b').textContent=typeof 42; document.getElementById('c').textContent=typeof true; document.getElementById('d').textContent=typeof null+' (quirk!)'; document.getElementById('e').textContent=typeof [1,2,3];" } },
      flow: ["value has a type", "typeof reports it", "null -> object (quirk)", "arrays are objects"],
      task: "Log the typeof of: \"0\", 0, \"\", [], null, and an object {}. Which results surprised you? (\"0\" is a string; [] is an object.) What's the one reliable way to test 'is this an array'?",
      mistake: "Trusting x === undefined for a variable that might not exist at all (it throws ReferenceError) — use typeof x === \"undefined\". And treating null and undefined as the same thing: in practice both mean 'no value', but they have different types and different uses.",
      tip: "The array check that actually works: Array.isArray([1,2]) — because typeof [] is \"object\", the same as a plain object. For 'is it a real object' you'll often use typeof x === \"object\" && x !== null (that last part excludes the quirk).",
      challenge: "A function should accept either a number or a numeric string (\"42\") and add 1. Write the type check(s) it needs, and decide what to do with \"hello\" (reject? convert? error?) — argue your choice." },

    { t: "Operators, === vs ==, and the = bug",
      text: "Use === (strict) and !== (strict not-equal): they compare value AND type, so \"5\" === 5 is false. The loose == does surprising type conversion (\"5\" == 5 is true) — avoid it. Math: + - * / and % (modulo, the remainder). The most famous beginner bug: if (x = 0) — a single = is an ASSIGNMENT, not a comparison; it sets x to 0 and the condition is always false.",
      def: "=== / !== are strict equality (no type conversion); + - * / % are arithmetic; a lone = inside a condition is assignment, a classic bug.",
      code: "\"5\" === 5   -> false  (strict)\n\"5\" == 5    -> true   (loose, avoid)\n4 + 1       -> 5\n7 % 3       -> 1      (remainder)\n\"5\" + 1     -> \"51\"   (string glue)\n\nTHE CLASSIC BUG:\nif (x = 0) { ... }   // assigns 0 to x!\nif (x === 0) { ... } // compares\n\nAlways === . Always.",
      out: { web: { h: "<p id=\"r1\"></p><p id=\"r2\"></p><p id=\"r3\"></p><p id=\"r4\"></p>", c: "body{font-family:monospace;background:#14171f;color:#eceae3;padding:24px;margin:0;font-size:13px}", j: "document.getElementById('r1').textContent='\"5\" === 5  ->  ' + (\"5\"===5); document.getElementById('r2').textContent='\"5\" == 5   ->  ' + (\"5\"==5); document.getElementById('r3').textContent='7 % 3      ->  ' + (7%3); document.getElementById('r4').textContent='\"5\" + 1    ->  ' + (\"5\"+1);" } },
      flow: ["=== compares value+type", "% = remainder", "+ glues strings", "one = is assignment"],
      task: "Predict, then verify in the console: \"3\" - 1, \"3\" + 1, 5 % 2, and 0 === false (loose) vs 0 === false (strict — wait, that's the same operator; use 0 == false vs 0 === false). What do the - and + operators do differently with a string?",
      mistake: "Using == out of habit (it works in most cases and fails in the weird ones — the worst kind of bug). And the assignment-in-condition bug: if (count = 0) — linting tools flag it for a reason; make it === and the bug can't exist.",
      tip: "Turn on a linter (ESLint's default rules) from day one — it catches = vs ===, unused variables, and undeclared names automatically. The tool does the checking; you do the learning.",
      challenge: "Why is \"0\" == false true but \"0\" === false false? Walk the type-conversion the loose operator performs, and explain why the strict operator's refusal is a feature, not a limitation." },

    { t: "Conditionals: if, else if, else, and the ternary",
      text: "if (condition) { ... } else if (other) { ... } else { ... } — exactly one branch runs, and the condition must be a boolean expression. For choosing between two VALUES (not running blocks), the ternary is the one-line form: const label = score >= 50 ? \"pass\" : \"retry\". Use ternaries for values, if blocks for logic.",
      def: "Conditionals run one of several blocks based on boolean tests; the ternary (cond ? a : b) picks one of two values inline.",
      code: "if (score >= 90) {\n  grade = \"A\";\n} else if (score >= 80) {\n  grade = \"B\";\n} else {\n  grade = \"C\";\n}\n\nTernary (values only):\nconst label = score >= 50\n  ? \"pass\" : \"retry\";\n\nCombine with && || !:\nif (age >= 18 && hasTicket)\n\nOrder matters: check the\nspecific cases first.",
      out: { web: { h: "<label>Score: <input id=\"s\" type=\"number\" value=\"85\" style=\"padding:6px;width:80px\"></label><button id=\"g\" style=\"padding:6px 12px;border:0;border-radius:6px;background:#14171f;color:#f5b23d;cursor:pointer\">grade it</button><p id=\"out\" style=\"font-size:20px;font-weight:bold\"></p>", c: "body{font-family:sans-serif;background:#faf7f0;color:#222;padding:24px;margin:0}", j: "function grade(s){ if(s>=90)return 'A'; else if(s>=80)return 'B'; else if(s>=50)return 'C'; return 'retry'; } document.getElementById('g').addEventListener('click',()=>{document.getElementById('out').textContent='score '+document.getElementById('s').value+' -> '+grade(+document.getElementById('s').value);});" } },
      flow: ["boolean test", "exactly one branch", "else if chains", "ternary for values"],
      task: "Build the grader above (number input + button + if/else if chain). Test the boundaries: 90, 89, 80, 79, 50, 49. Which score does each boundary belong to, and is that what you intended?",
      mistake: "Checking conditions in the wrong order (if score > 50 ... else if score > 80 — the first true one wins, so the 80+ case never runs). Put the most specific/highest condition first in an if/else-if chain.",
      tip: "The condition is a yes/no question — if you can't read it as one (\"if score\" instead of \"if score >= 50\"), it's a bug waiting to happen. Write conditions like English: if the score is at least 50.",
      challenge: "Rewrite the grader as a single expression using nested ternaries. Then answer honestly: was it more readable? (The lesson: ternaries are for simple value picks, not complex logic — know when the one-liner becomes a knot.)" },

    { t: "Loops: for, for...of, and while",
      text: "Three forms, one idea. The index loop: for (let i = 0; i < items.length; i++) — when you need the position. The clean one: for (const item of items) — go through values (the modern default for arrays). The condition loop: while (condition) — repeat until something changes. Always change something inside a while loop or it runs forever.",
      def: "Loops repeat a block: for (counted/indexed), for...of (each item), while (until a condition flips).",
      code: "const fruits = [\"apple\", \"banana\", \"cherry\"];\n\n// for...of: the default\nfor (const f of fruits) console.log(f);\n\n// for: when you need the index\nfor (let i = 0; i < fruits.length; i++)\n  console.log(i + \": \" + fruits[i]);\n\n// while: until a condition flips\nlet water = 3;\nwhile (water > 0) {\n  console.log(\"drink\");\n  water--;            // MUST change!\n}",
      out: { web: { h: "<p id=\"o\"></p>", c: "body{font-family:monospace;background:#14171f;color:#9fe8d8;padding:24px;margin:0;font-size:13px;white-space:pre-wrap}", j: "let out=''; const fruits=['apple','banana','cherry']; for(const f of fruits) out+=f+'\\n'; out+='--- with index ---\\n'; for(let i=0;i<fruits.length;i++) out+=i+': '+fruits[i]+'\\n'; let w=3; while(w>0){out+='drink ('+w+' left)\\n';w--;} document.getElementById('o').textContent=out;" } },
      flow: ["pick the form", "for...of for values", "for for indices", "while changes something"],
      task: "Loop through [3, 7, 1, 9, 4] three ways: for...of (log each), for (log index + value), and a while loop with a counter. Same output? Which form felt least error-prone, and when would you NEED the index?",
      mistake: "A while loop whose condition never becomes false (the body forgets to update the counter) — the page freezes and only a refresh helps. And off-by-one in the classic for: i <= items.length reads one past the end (undefined). It's i < length.",
      tip: "Reach for for...of by default; only drop to the indexed for when you need the position (or to skip/swapping items). If you find yourself doing items[i] inside for...of, you mixed the forms — pick one.",
      challenge: "Write a while loop that prints the multiplication table row for 7 (7×1 to 7×9). Then convert it to a for loop. Which variable plays the 'changes each pass' role in each version?" },

    { t: "Functions and arrow functions",
      text: "Define a function to name a reusable block of steps: function add(a, b) { return a + b }. The modern shorthand is the arrow form: const add = (a, b) => a + b (one-line bodies skip braces and return). A callback is a function you pass to another function, which calls it later — setTimeout(fn, 1000), addEventListener(\"click\", fn), array.map(fn). Callbacks are how JavaScript coordinates: \"do X, then call me.\"",
      def: "Functions are named reusable code with parameters and a return; arrows (=>) are the concise form; callbacks are functions passed to be called later.",
      code: "function add(a, b) {\n  return a + b;\n}\n\nconst add = (a, b) => a + b;  // arrow\n\nadd(2, 3)  -> 5\n\nCallbacks (pass a function in):\nsetTimeout(() => console.log(\"hi\"), 1000);\nbtn.addEventListener(\"click\", () => {\n  /* runs later, on click */\n});\nnums.map(n => n * 2)\n\nNote: () => is REQUIRED after the\nname — handler() would CALL it now.",
      out: { web: { h: "<button id=\"t\" style=\"padding:10px 16px;border:0;border-radius:8px;background:#14171f;color:#f5b23d;cursor:pointer\">count from 3</button><p id=\"o\" style=\"font-weight:bold\"></p>", c: "body{font-family:sans-serif;background:#faf7f0;color:#222;padding:24px;margin:0}", j: "document.getElementById('t').addEventListener('click',()=>{ let n=3; const tick=()=>{ document.getElementById('o').textContent=n; if(n===0)return; n--; setTimeout(tick,600); }; tick(); });" } },
      flow: ["define once", "call with args", "return the result", "pass as callback later"],
      task: "Write both forms of a function that returns the larger of two numbers (classic + arrow). Then use setTimeout with an arrow callback to show a \"done\" message 1 second after a button click. What ran immediately, and what ran later?",
      mistake: "Calling the function where you should pass it: addEventListener(\"click\", handler()) runs handler NOW (once) and passes its result — the classic \"why didn't my button work?\" bug. Pass the name (or an arrow wrapping the call), not a call.",
      tip: "Arrow functions have no own `this` (they inherit it) — for simple logic that's invisible, but it matters inside object methods and classes. When in doubt and you're not in a class, arrows are safe and short.",
      challenge: "What's the output order here, and why? const f = () => console.log(\"B\"); setTimeout(f, 0); console.log(\"A\"); — (hint: setTimeout is asynchronous, even at 0ms.)" },

    { t: "Arrays and the methods that do the work",
      text: "Arrays are ordered lists, and their methods are the workhorses: push() adds, .length is the count, .includes(x) checks, .map() transforms every item into a new array, .filter() keeps items that pass a test, .find() gets the first match, .reduce() folds the array into one value. Chaining is normal: users.filter(u => u.active).map(u => u.name). map and filter don't change the original — they return new arrays.",
      def: "Array methods: push/length/includes for basics; map (transform), filter (select), find (first match), reduce (fold to one value) for data work — most return new arrays.",
      code: "const prices = [5, 12, 3, 8];\n\nprices.length          -> 4\nprices.includes(12)    -> true\nprices.map(p => p * 2) -> [10,24,6,16] (new)\nprices.filter(p => p > 5) -> [12, 8]\nprices.find(p => p < 4)  -> 3\nprices.reduce((s,p) => s + p, 0) -> 28\n\nChain them:\nactiveUsers.map(u => u.name)\n\nmap/filter never touch the\noriginal array.",
      out: { web: { h: "<p id=\"o\" style=\"font-family:monospace;font-size:13px;white-space:pre-wrap\"></p>", c: "body{font-family:sans-serif;background:#14171f;color:#9fe8d8;padding:24px;margin:0}", j: "const prices=[5,12,3,8]; const lines=['prices = '+JSON.stringify(prices),'','map x2:      '+JSON.stringify(prices.map(p=>p*2)),'filter >5:   '+JSON.stringify(prices.filter(p=>p>5)),'find <4:     '+prices.find(p=>p<4),'reduce sum:  '+prices.reduce((s,p)=>s+p,0),'','original:    '+JSON.stringify(prices)+' (unchanged)']; document.getElementById('o').textContent=lines.join('\\n');" } },
      flow: ["push / length / includes", "map = transform", "filter = select", "find / reduce", "chain them"],
      task: "Given scores = [70, 85, 60, 95, 40]: use filter to keep the passing ones (>= 50), map the result to add a \"%\" suffix, and reduce to the average of the passing scores. Three chained expressions — write them.",
      mistake: "Mutating the original in a map loop (pushing to the same array you're reading) or expecting filter to modify the list in place — both return a NEW array; if you don't capture it (const passing = ...), the result is lost.",
      tip: "Learn the shape of reduce: (accumulator, item) => nextAccumulator, with a start value. It's the one method that looks scary until you write it five times — after that, \"fold this into one number\" is just reduce.",
      challenge: "You have [1, 2, 2, 3, 3, 3]. Write an expression (one or two methods) that returns the unique values [1, 2, 3]. (Hint: there's a built-in type that stores only unique values — convert, then back.)" },

    { t: "Objects: data with meaning",
      text: "Objects group related values under named keys: const user = { name: \"Ada\", age: 36 }. Read with dot (user.name) or brackets (user[\"name\"]) — brackets let you build the key dynamically. Objects are passed by reference: a = user doesn't copy, it points to the same object — the famous source of \"why did my data change?\" bugs. Real programs are built mostly from objects: users, config, API responses, database rows.",
      def: "An object is a collection of key-value pairs (and methods); accessed by dot or bracket notation; passed by reference, not copied.",
      code: "const user = {\n  name: \"Ada\",\n  age: 36,\n  isAdmin: true,\n  greet() { return \"Hi, I'm \" + this.name; }\n};\n\nuser.name            -> \"Ada\"\nuser[\"age\"]          -> 36\nuser[lang]           // dynamic key\n\"email\" in user      -> false\nuser.email = \"a@x.com\"  // add a key\n\nReference, not copy:\nconst alias = user;\nalias.name = \"Moa\";\nuser.name          -> \"Moa\" (!)",
      out: { web: { h: "<p id=\"o\" style=\"font-family:monospace;font-size:13px;white-space:pre-wrap\"></p>", c: "body{font-family:sans-serif;background:#14171f;color:#9fe8d8;padding:24px;margin:0}", j: "const user={name:'Ada',age:36,greet(){return 'Hi, I\\u2019m '+this.name;}}; const alias=user; alias.name='Moa'; const lines=['user = {name:\"Ada\", age:36}','alias = user   (same object!)','alias.name = \"Moa\"','user.name -> '+user.name+'  (changed!)','user.greet() -> '+user.greet()]; document.getElementById('o').textContent=lines.join('\\n');" } },
      flow: ["keys hold values", "dot / bracket access", "methods live inside", "reference, not copy"],
      task: "Build a product object: { name, price, inStock }. Add a method priceWithTax() that returns price * 1.07. Then create a 'copy' with const promo = product and change promo.price — did product.price change too? Explain what happened.",
      mistake: "Assuming a = obj copies the object (it doesn't — both names point at the same thing, so a change through one shows through the other). For a real copy you need to make one explicitly (spread: { ...product }).",
      tip: "Bracket notation is the underused tool: user[\"first \" + part] builds a key from data. It's how you read dynamic responses (response[statusKey]) and how object.keys() / for...in let you loop over an object's own properties.",
      challenge: "Why can't an array be an object's key ({ [1,2]: \"x\" } doesn't behave like you'd expect), and what's the standard workaround for 'nested lookup by a list of values'?" },

    { t: "The DOM: finding elements on the page",
      text: "The DOM is the live, in-memory tree of your page that JavaScript can read and change. Find elements with document.querySelector(\".card\") (first match, any CSS selector) or querySelectorAll(\".card\") (all matches, as a list). querySelector is the modern default — you already know CSS selectors, so you already know how to find things. Once you have the element, the page is editable: text, classes, styles, attributes.",
      def: "The DOM is the browser's object tree of the page; querySelector/querySelectorAll find nodes with CSS selectors, giving JS a handle to read and modify the page.",
      code: "const card = document.querySelector(\".card\");\nconst all  = document.querySelectorAll(\".card\");\n\nall.forEach(c => c.style.opacity = 0.5);\n\n// by id (also fine):\nconst out = document.getElementById(\"out\");\n\n// create + add:\nconst p = document.createElement(\"p\");\np.textContent = \"added by JS\";\ndocument.body.appendChild(p);\n\nThe page is DATA to JS.\nRead it, change it, add to it.",
      out: { web: { h: "<div class=\"card\" id=\"c1\">Card 1</div><div class=\"card\" id=\"c2\">Card 2</div><button id=\"dim\" style=\"margin-top:12px;padding:8px 14px;border:0;border-radius:6px;background:#14171f;color:#f5b23d;cursor:pointer\">dim all cards (querySelectorAll)</button>", c: "body{font-family:sans-serif;background:#faf7f0;color:#222;padding:24px;margin:0} .card{background:#fff;border:1px solid #ddd;border-radius:10px;padding:16px;margin-top:8px;transition:opacity .3s}", j: "document.getElementById('dim').addEventListener('click',()=>{document.querySelectorAll('.card').forEach(c=>c.style.opacity=c.style.opacity==='0.3'?'':'0.3');});" } },
      flow: ["page = DOM tree", "querySelector (CSS)", "one or all", "read / modify / create"],
      task: "On this lesson's page: querySelector the first .card, querySelectorAll all of them, change the second card's text, and append a new <p> to the body. Which calls returned a single element vs a list?",
      mistake: "Using getElementById for everything and querySelector for the rest (pick one system — querySelector handles all cases with CSS you already know) or forgetting querySelector returns the FIRST match (for the rest, use querySelectorAll).",
      tip: "Think of the DOM as editable data: the page is a tree of objects, and 'changing the UI' is just setting properties on those objects. That mental shift — UI = data — is what makes JS on the web click into place.",
      challenge: "document.querySelector(\"#app .item\") vs querySelector(\"#app\") .querySelector(\".item\") — is there any difference in what they find? When WOULD scoping to a parent matter (hint: duplicate class names on a big page)?" },

    { t: "Changing the page: text, classes, and styles",
      text: "Once you have an element, the four ways to change it: textContent (its text), classList (add/remove/toggle classes — the clean way to restyle), style (one-off inline properties), and setAttribute (any attribute). Prefer classList for design changes — it keeps the styling in your stylesheet where it belongs, and toggle() is the one-liner for show/hide-by-class.",
      def: "Element APIs: textContent (text), classList.add/remove/toggle (classes), style (inline props), setAttribute (attributes) — classList is the preferred styling path.",
      theme: "dark",
      code: "const btn = document.querySelector(\".btn\");\n\n// text\nout.textContent = \"Score: \" + score;\n\n// classes (the clean way)\ncard.classList.add(\"active\");\ncard.classList.toggle(\"hidden\");\n\n// one-off style\nel.style.color = \"red\";   // avoid for design\n\n// attribute\nlink.setAttribute(\"href\", url);\n\nDesign changes = classList.\nInline style = emergencies only.",
      out: { web: { h: "<div class=\"note\" id=\"n\">I start calm.</div><button class=\"b\" id=\"a\" style=\"padding:8px 14px;border:0;border-radius:6px;background:#14171f;color:#f5b23d;cursor:pointer;margin-right:8px\">add .loud</button><button class=\"b\" id=\"t\" style=\"padding:8px 14px;border:0;border-radius:6px;background:#14171f;color:#f5b23d;cursor:pointer\">toggle .hidden</button>", c: "body{font-family:sans-serif;background:#faf7f0;color:#222;padding:24px;margin:0} .note{background:#fff;border:1px solid #ddd;border-radius:10px;padding:18px;margin-bottom:12px;transition:all .25s} .loud{background:#f5b23d;font-weight:bold;transform:scale(1.03)} .hidden{display:none}", j: "const n=document.getElementById('n'); document.getElementById('a').addEventListener('click',()=>n.classList.add('loud')); document.getElementById('t').addEventListener('click',()=>n.classList.toggle('hidden'));" } },
      flow: ["get the element", "textContent for words", "classList for design", "style for one-offs"],
      task: "Build a note box with three buttons: one adds a 'highlight' class, one toggles a 'dimmed' class, one changes its textContent. Notice which changes live in CSS and which in JS — and why classList keeps your design maintainable.",
      mistake: "Styling with el.style.property for every visual change (the design leaks into JS strings, and your stylesheet can no longer reach those elements — inline style beats the sheet). classList keeps the rule in CSS and the switch in JS.",
      tip: "textContent vs innerHTML: textContent inserts plain text (safe), innerHTML parses HTML (powerful, but dangerous with user input — it's how XSS attacks happen). Default to textContent; reach for innerHTML only with trusted, static markup.",
      challenge: "Why does el.style.display = \"\" restore an element's display, but el.style.display = el.style.display doesn't help after you set it to \"none\"? What's the robust show/hide pattern (hint: it's not in the style object at all)?" },

    { t: "Events and listeners: reacting to the user",
      text: "Events are how the page tells your code something happened: click, input, submit, keydown, scroll... Attach a handler with element.addEventListener(\"click\", () => { ... }). The handler receives an event object with details: event.target (what was clicked), event.key (which key), event.preventDefault() (stop the default action). The classic bug: passing handler() instead of handler — the () calls it immediately.",
      def: "addEventListener(type, handler) registers a function to run when an event fires; the handler gets an event object with context and controls (like preventDefault).",
      code: "btn.addEventListener(\"click\", (event) => {\n  console.log(\"clicked\", event.target);\n});\n\ninput.addEventListener(\"input\", (e) => {\n  live.textContent = e.target.value;\n});\n\nform.addEventListener(\"submit\", (e) => {\n  e.preventDefault();   // stop the reload\n  // handle the data...\n});\n\nTHE BUG: addEventListener(\"click\", handler())\n() runs it NOW. Pass the function, not a call.",
      out: { web: { h: "<button id=\"b\" style=\"padding:10px 16px;border:0;border-radius:8px;background:#14171f;color:#f5b23d;cursor:pointer\">click me</button><input id=\"i\" placeholder=\"type: watch it live\" style=\"padding:8px;margin-left:10px;border:1px solid #ccc;border-radius:6px\"><p id=\"o\" style=\"font-family:monospace;font-size:13px;color:#555\">waiting for events...</p>", c: "body{font-family:sans-serif;background:#faf7f0;color:#222;padding:24px;margin:0}", j: "let clicks=0; const o=document.getElementById('o'); document.getElementById('b').addEventListener('click',(e)=>{clicks++;o.textContent='click #'+clicks+' on '+e.target.tagName.toLowerCase()+' — event.target told me.';}); document.getElementById('i').addEventListener('input',(e)=>{o.textContent='live input: \"'+e.target.value+'\" (fires on every keystroke)';});" } },
      flow: ["event happens", "listener fires", "handler runs", "event object gives context"],
      task: "Build a button that counts clicks (with event.target in the message) and an input that updates a preview on every keystroke (the \"input\" event). Which event fires once per click vs once per keystroke?",
      mistake: "The handler() bug (calling the function in the argument — it runs once at setup, and the listener gets its undefined result). And using onclick=\"...\" inline attributes instead of addEventListener (they work, but they mix behavior into the HTML and are harder to manage — one listener system to rule them all).",
      tip: "The event object is a toolbox: .target (what triggered it), .preventDefault() (cancel the browser's default — page reload on submit, link navigation), .key (keyboard events), .clientX/Y (position). You don't need all of it — but know it's there when you need it.",
      challenge: "A form submits and the page reloads, losing your JS state. Where do you call preventDefault, on which event, and why does calling it on \"click\" of the submit button not always work (hint: submit can happen without a click — the Enter key)?" },

    { t: "Handling forms in JavaScript",
      text: "The pattern: listen for the form's \"submit\" event, call event.preventDefault() to stop the reload, then read the values. Two ways to read: input.value per field, or new FormData(form) for the whole thing at once (it respects name attributes). Validate before acting, show a clear message, and never trust the input — the browser's type=\"email\" is a hint, not a guarantee.",
      def: "Form handling: submit event + preventDefault, read via .value or FormData, validate, then act — the standard flow for any interactive form.",
      code: "const form = document.querySelector(\"form\");\n\nform.addEventListener(\"submit\", (e) => {\n  e.preventDefault();          // no reload\n  const data = new FormData(form);\n  const name = data.get(\"name\");\n  const email = data.get(\"email\");\n\n  if (!name || !email) {\n    out.textContent = \"both fields are required\";\n    return;\n  }\n  out.textContent = \"hello, \" + name + \"!\";\n});\n\nEach input needs a name=\"...\"\nfor FormData to see it.",
      out: { web: { h: "<form id=\"f\" style=\"display:grid;gap:10px;max-width:280px\"><input id=\"n\" name=\"name\" placeholder=\"name\" style=\"padding:10px;border:1px solid #ccc;border-radius:6px\"><input id=\"e\" name=\"email\" type=\"email\" placeholder=\"email\" style=\"padding:10px;border:1px solid #ccc;border-radius:6px\"><button type=\"submit\" style=\"padding:10px;border:0;border-radius:6px;background:#14171f;color:#f5b23d;font-weight:bold;cursor:pointer\">Sign up</button></form><p id=\"out\" style=\"font-weight:bold;color:#2c8a63\"></p>", c: "body{font-family:sans-serif;background:#faf7f0;color:#222;padding:24px;margin:0}", j: "const f=document.getElementById('f'), out=document.getElementById('out'); f.addEventListener('submit',(e)=>{ e.preventDefault(); const d=new FormData(f); const n=d.get('name'), em=d.get('email'); if(!n||!em){out.textContent='both fields are required';out.style.color='#c0392b';return;} out.style.color='#2c8a63'; out.textContent='hello, '+n+'! (email: '+em+')'; });" } },
      flow: ["submit event", "preventDefault", "read (FormData)", "validate", "act + show result"],
      task: "Build the signup form above with real validation: name required, email must contain @ and . (your own check, not the browser's). Show a different message per failure. Test with: empty, no email, bad email, all good.",
      mistake: "Reading inputs by id instead of name (FormData is name-based) or skipping validation because type=\"email\" exists (users can disable validation, and 'x' passes a loose check in some contexts). Validate in JS as the source of truth; browser types are a courtesy.",
      tip: "new FormData(form) is the underused gem: it reads every named control in the form in one call, including checkboxes and selects. For a 5-field form it replaces 5 lines of .value reads — and it's what you'll send to a server later.",
      challenge: "Why must preventDefault be called inside the submit listener (not before it, or on the button's click)? Walk the event sequence of pressing Enter in a form field and say exactly where the reload would happen if you forgot it." },

    { t: "Timers: setTimeout and setInterval",
      text: "setTimeout(fn, ms) runs fn once after the delay; setInterval(fn, ms) repeats it until you clearInterval(id). Both return an id you need to cancel. Common uses: close a toast after 3 seconds, poll a status every 5 seconds, drive a typewriter effect. Remember JavaScript is single-threaded: the delay doesn't pause your code — it schedules the callback for later while everything else keeps running.",
      def: "setTimeout (once, after a delay) and setInterval (repeating) schedule callbacks; both return an id for clearTimeout/clearInterval.",
      code: "setTimeout(() => {\n  toast.style.display = \"none\";\n}, 3000);          // once, after 3s\n\nconst id = setInterval(() => {\n  count++; show(count);\n}, 1000);           // every second\n\n// stop it:\nclearInterval(id);\n\nJS is single-threaded: the delay\nschedules — it doesn't pause\nthe rest of your code.",
      out: { web: { h: "<button id=\"s\" style=\"padding:10px 16px;border:0;border-radius:8px;background:#14171f;color:#f5b23d;cursor:pointer\">start 3s countdown</button><p id=\"o\" style=\"font-size:22px;font-weight:bold\">—</p><p id=\"t\" style=\"font-size:12px;color:#888\">the \"toast\" below disappears by itself (setTimeout)</p><div id=\"toast\" style=\"background:#2c8a63;color:#fff;padding:10px 14px;border-radius:8px;display:inline-block\">toast: saved!</div>", c: "body{font-family:sans-serif;background:#faf7f0;color:#222;padding:24px;margin:0}", j: "setTimeout(()=>{document.getElementById('toast').style.display='none';},3000); let iv=null; document.getElementById('s').addEventListener('click',()=>{ if(iv){clearInterval(iv);iv=null;document.getElementById('o').textContent='—';return;} let n=3; document.getElementById('o').textContent=n; iv=setInterval(()=>{ n--; document.getElementById('o').textContent=n>0?n:'done!'; if(n<=0){clearInterval(iv);iv=null;} },1000); });" } },
      flow: ["schedule a callback", "setTimeout = once", "setInterval = repeat", "clear to stop"],
      task: "Build the countdown above: a button starts a 3-2-1-done sequence with setInterval, and clicking again stops it (clearInterval). Then make a toast that auto-hides after 3 seconds with setTimeout. What happens if you start two countdowns at once in your version?",
      mistake: "Forgetting to clearInterval (the interval keeps running after its job is done — leaks, double-counts, surprises) or thinking setTimeout pauses the page (it doesn't; the main thread keeps running other code until the delay elapses).",
      tip: "For 'do X, wait, do Y, wait, do Z' chains, a setTimeout that schedules the next step (recursively) is often cleaner than setInterval — you control each delay individually and there's no id to manage. setInterval is for true repetition.",
      challenge: "Why does this print 0 five times? let x = 0; for (let i = 0; i < 5; i++) setTimeout(() => console.log(x), 100); — (hint: when do the callbacks actually run, relative to the loop?) How would you make it print 0,1,2,3,4?" },

    { t: "localStorage: remembering things between visits",
      text: "localStorage keeps simple string values in the browser forever (until cleared): localStorage.setItem(\"score\", 42) to save, getItem to read, removeItem to delete. Values must be strings, so objects need JSON.stringify() to save and JSON.parse() to read. Perfect for settings, progress, and to-do lists — no server, no account. This is exactly how MeenLearn saves your lesson progress.",
      def: "localStorage is a browser key-value store that persists between visits; values are strings, so objects are stored as JSON (stringify to save, parse to read).",
      code: "// save\nlocalStorage.setItem(\"theme\", \"dark\");\nlocalStorage.setItem(\"todos\", JSON.stringify(todos));\n\n// read\nconst theme = localStorage.getItem(\"theme\");\nconst todos = JSON.parse(\n  localStorage.getItem(\"todos\") || \"[]\"\n);\n\n// delete\nlocalStorage.removeItem(\"theme\");\n\nStrings only -> JSON for objects.\nGone when the user clears site data.",
      out: { web: { h: "<p>Type a note — it survives a refresh (try it):</p><input id=\"i\" style=\"padding:10px;width:220px;border:1px solid #ccc;border-radius:6px\"><p id=\"o\" style=\"font-size:12px;color:#888\"></p>", c: "body{font-family:sans-serif;background:#faf7f0;color:#222;padding:24px;margin:0}", j: "const i=document.getElementById('i'), o=document.getElementById('o'); i.value=localStorage.getItem('meen-note')||''; if(i.value)o.textContent='restored from localStorage: \"'+i.value+'\"'; i.addEventListener('input',()=>{ localStorage.setItem('meen-note',i.value); o.textContent='saved to localStorage (refresh to prove it)'; });" } },
      flow: ["setItem(key, value)", "strings only", "JSON for objects", "survives refresh/visits"],
      task: "Build the note box above: type → saves on every keystroke, refresh → restores. Then store an object (a to-do list array) with JSON.stringify/parse and prove it round-trips. What happens if you read a key that was never set?",
      mistake: "Storing an object directly (localStorage.setItem(\"x\", {a:1}) silently saves the string \"[object Object]\") — you MUST JSON.stringify. And reading with JSON.parse(null) throws — guard with getItem(...) || \"[]\" first.",
      tip: "localStorage is per-origin (this site can't read another site's data) and synchronous (it blocks briefly — fine for small values). Don't store huge blobs or secrets; it's for lightweight user state, exactly the kind MeenLearn uses for progress.",
      challenge: "Two tabs are open on the same page; tab A writes a key. What does tab B see (and when)? (Hint: there's an event for this.) Why does that make localStorage great for settings but a poor choice for a shared to-do list across devices?" },

    { t: "Working with data: arrays of objects",
      text: "Real programs juggle arrays of objects: a list of users, products, orders. The pattern: filter the list, map it to what you need, reduce it to a summary — then render it to the page. This one loop (data in → transform → DOM out) is the shape of almost every interactive app, from a to-do list to a dashboard.",
      def: "The data flow of apps: an array of objects is the source; filter/map/reduce transform it; the result is rendered into the DOM. Data in, DOM out.",
      code: "const products = [\n  { name: \"Tea\",   price: 2,  stock: true },\n  { name: \"Coffee\",price: 4,  stock: true },\n  { name: \"Milk\",  price: 1,  stock: false },\n];\n\n// filter -> map -> render\nconst available = products\n  .filter(p => p.stock)\n  .map(p => `${p.name} — $${p.price}`);\n\navailable.forEach(line => {\n  const li = document.createElement(\"li\");\n  li.textContent = line;\n  list.appendChild(li);\n});\n\nData in -> transform -> DOM out.",
      out: { web: { h: "<p>In stock:</p><ul id=\"list\" style=\"font:14px sans-serif\"></ul><p id=\"total\" style=\"font-weight:bold\"></p>", c: "body{font-family:sans-serif;background:#faf7f0;color:#222;padding:24px;margin:0}", j: "const products=[{name:'Tea',price:2,stock:true},{name:'Coffee',price:4,stock:true},{name:'Milk',price:1,stock:false},{name:'Biscuit',price:3,stock:true}]; const list=document.getElementById('list'); products.filter(p=>p.stock).map(p=>p.name+' — $'+p.price).forEach(l=>{const li=document.createElement('li');li.textContent=l;list.appendChild(li);}); const total=products.filter(p=>p.stock).reduce((s,p)=>s+p.price,0); document.getElementById('total').textContent='total if you buy everything in stock: $'+total;" } },
      flow: ["array of objects", "filter the list", "map to display", "reduce to summary", "render to DOM"],
      task: "Extend the product list: add a 'category' field, filter to one category, and show both the item list AND a reduced total. Then add a button that adds a new product to the array and re-renders the list from scratch. What's the lesson about 'the data is the source of truth'?",
      mistake: "Rendering by hand (writing each <li> in HTML) and then updating it piecewise with JS — the moment the data and the DOM drift apart, bugs follow. Keep the data as the source and re-render from it; the DOM is a picture of the data, not the data itself.",
      tip: "Name your pipeline steps like a story: availableProducts = products.filter(inStock); lines = availableProducts.map(toLine); render(lines). Readable pipelines debug themselves — when the output is wrong, you know which step to look at.",
      challenge: "Your to-do app stores todos in localStorage as an array of {text, done}. Write the three-step pipeline (load → toggle one → save + re-render) for a 'mark done' button. Which step is the only one that touches localStorage?" },

    { t: "Errors and try/catch: failing gracefully",
      text: "try { risky code } catch (error) { handle it } finally { always runs }. Use it around things that can fail: JSON.parse of user input, network requests, file reads. Instead of your app crashing with a mystery, you show a friendly message or a fallback value. throw lets you raise your own errors. The skill: expect the failure paths, and decide what 'graceful' looks like before the error finds you.",
      def: "try/catch/finally wraps code that may throw; catch handles the error (with the error object), finally always runs; throw raises an error deliberately.",
      code: "function load(name) {\n  const raw = localStorage.getItem(name);\n  try {\n    return JSON.parse(raw || \"[]\");\n  } catch (error) {\n    console.error(\"bad data for\", name, error);\n    return [];          // graceful fallback\n  }\n}\n\nthrow new Error(\"id required\");\n\ntry { ... } catch (e) { ... }\nfinally { ... always ... }\n\nExpect failures. Decide the\nfallback BEFORE you need it.",
      out: { web: { h: "<input id=\"i\" placeholder='type {\"a\":1} or just \"hello\"' style=\"padding:10px;width:230px;border:1px solid #ccc;border-radius:6px\"><button id=\"p\" style=\"padding:10px 14px;border:0;border-radius:6px;background:#14171f;color:#f5b23d;cursor:pointer\">JSON.parse it</button><pre id=\"o\" style=\"font:12px monospace;background:#14171f;color:#9fe8d8;padding:12px;border-radius:8px;white-space:pre-wrap\"></pre>", c: "body{font-family:sans-serif;background:#faf7f0;color:#222;padding:24px;margin:0}", j: "document.getElementById('p').addEventListener('click',()=>{ const raw=document.getElementById('i').value; const o=document.getElementById('o'); try{ const v=JSON.parse(raw); o.textContent='parsed OK:\\n'+JSON.stringify(v,null,2); }catch(e){ o.style.color='#e2664f'; o.textContent='Graceful catch — no crash:\\n'+e.message; } });" } },
      flow: ["risky code in try", "throws?", "catch handles it", "finally always runs", "fallback, not crash"],
      task: "Build the JSON parser above: valid input shows the parsed object, invalid input shows a friendly caught message (no crash). Then add a finally block that logs 'attempt done' — confirm it runs for BOTH valid and invalid input.",
      mistake: "A bare catch that swallows the error silently (the bug is now invisible — at minimum, console.error it) or catching everything with one broad handler (catch the specific error you expect; let unexpected ones surface). And: don't use try/catch as flow control for normal cases (if the parse fails 9 times out of 10, that's not 'risky', it's the main path).",
      tip: "The question to ask before any risky line: 'what does graceful look like here?' A fallback value, a retry, a message, a default state — deciding that first is what separates professional code from crash-prone code.",
      challenge: "Why does JSON.parse(\"{a:1}\") throw but JSON.parse('{\"a\":1}') doesn't? Write a try/catch that specifically detects 'this looked like JSON but isn't valid' and gives a different message than 'this isn't JSON at all'." },

    { t: "fetch: talking to a server",
      text: "fetch(url) asks a server for data and returns a Promise: the modern form is async/await — const res = await fetch(url); const data = await res.json();. Two beginner gotchas: (1) fetch only rejects on network failure — a 404 still resolves, so always check res.ok; (2) the server must allow your site (CORS), or the browser blocks the response. You'll use fetch to load JSON from APIs — the bridge from 'page' to 'application'.",
      def: "fetch(url) performs an HTTP request, returning a Promise; await fetch + res.json() is the standard read; check res.ok and expect CORS constraints.",
      code: "async function loadUsers() {\n  const res = await fetch(\"/api/users\");\n  if (!res.ok) {\n    throw new Error(\"HTTP \" + res.status);\n  }\n  const users = await res.json();\n  return users;\n}\n\n// then call it:\nloadUsers().then(render).catch(showError);\n\nGotchas:\n- fetch resolves on 404 too -> check res.ok\n- CORS: the server must allow\n  your origin, or the browser\n  blocks the response",
      out: { web: { h: "<button id=\"f\" style=\"padding:10px 16px;border:0;border-radius:8px;background:#14171f;color:#f5b23d;cursor:pointer\">fetch a JSON API</button><pre id=\"o\" style=\"font:12px monospace;background:#14171f;color:#9fe8d8;padding:12px;border-radius:8px;white-space:pre-wrap;min-height:60px\">ready…</pre>", c: "body{font-family:sans-serif;background:#faf7f0;color:#222;padding:24px;margin:0}", j: "document.getElementById('f').addEventListener('click',async()=>{ const o=document.getElementById('o'); o.style.color='#9fe8d8'; o.textContent='fetching…'; try{ const res=await fetch('https://jsonplaceholder.typicode.com/users/1'); if(!res.ok) throw new Error('HTTP '+res.status); const u=await res.json(); o.textContent='res.ok = true\\nname: '+u.name+'\\ncompany: '+u.company.name; }catch(e){ o.style.color='#e2664f'; o.textContent='caught: '+e.message+'\\n(no network in this sandbox? that\\u2019s a real fetch failure — handled gracefully)'; } });" } },
      flow: ["fetch(url) -> Promise", "await the response", "check res.ok", "await res.json()", "render / handle error"],
      task: "Build the fetch button above (it calls a public JSON API). Study both paths: the success render and the caught error. Then add a second button that fetches a non-existent URL and confirm you detect it via res.ok (not just the catch).",
      mistake: "Trusting fetch to fail on 404 (it doesn't — the response arrives with status 404 and fetch considers that 'success'); you must check res.ok yourself. And: a CORS error appears as a network-style failure in catch, which is confusing — the request was blocked by the browser policy, not the network.",
      tip: "The async/await form reads top-to-bottom like synchronous code (await pauses only this function, not the page). For new code, default to async/await; save the .then() chains for when you need to compose them explicitly.",
      challenge: "Why does const data = await res.json() appear TWICE in the pattern (two awaits, two steps)? What is each await actually waiting for, and what would you get if you skipped the second one?" },

    { t: "async/await and Promises, demystified",
      text: "A Promise is a future value: something that will resolve (succeed with a value) or reject (fail with an error) later — network calls, timers, file reads. await pauses an async function until the promise settles, making asynchronous code read top-to-bottom. Rules: await only works inside async functions; it never blocks the page (other code keeps running while it waits). This is the mental model behind every 'load data, then render' flow.",
      def: "A Promise represents a future value (resolves or rejects); await (inside async functions) pauses until it settles, making async code linear to read without blocking the page.",
      code: "const p = new Promise((resolve, reject) => {\n  setTimeout(() => resolve(42), 1000);\n});\n\nasync function main() {\n  const answer = await p;   // waits 1s\n  console.log(answer);      // 42\n}\nmain();\n\nawait rules:\n- only inside async functions\n- pauses THIS function, not the page\n- value = the resolved value\n- error = go to the catch\n\nPromise = 'a value, coming.'",
      out: { web: { h: "<button id=\"go\" style=\"padding:10px 16px;border:0;border-radius:8px;background:#14171f;color:#f5b23d;cursor:pointer\">start (1s promise)</button><p id=\"o\" style=\"font-weight:bold\"></p>", c: "body{font-family:sans-serif;background:#faf7f0;color:#222;padding:24px;margin:0}", j: "const o=document.getElementById('o'); document.getElementById('go').addEventListener('click',async()=>{ o.textContent='waiting for the promise… (page still responsive)'; const val=await new Promise(r=>setTimeout(()=>r('the answer'),1000)); o.textContent='promise resolved: '+val; });" } },
      flow: ["a value, coming (Promise)", "await it (inside async)", "paused, not blocked", "value or error"],
      task: "Build the promise demo above. While it's waiting, confirm the page is still responsive (can you hover, scroll, click other things?). Then convert the fetch lesson's code from .then() chains to async/await — which version is easier to read, and why?",
      mistake: "Using await outside an async function (SyntaxError) or believing await freezes the whole page (it doesn't — the event loop keeps serving other events; only THIS function is paused). The 'frozen UI' problem is a different bug: a long synchronous loop, not an await.",
      tip: "Think of await as 'I'll come back to this line when the value arrives' — the function yields, other code runs, and execution resumes with the value in hand. That single picture explains fetch, storage reads, and timers all at once.",
      challenge: "What's the output order, and why? async function a(){ console.log('a1'); await new Promise(r=>setTimeout(r,500)); console.log('a2'); } a(); console.log('b'); — (hint: what does the first line of a do before it hits the await?)" },

    { t: "Modular thinking: small functions, clear names",
      text: "The difference between code that survives and code that rots is function size. A function should do ONE thing and be nameable in a sentence: 'compute the discount', 'format the date', 'render the row'. If the name needs 'and', split it. Small, named functions are testable in isolation, reusable, and readable — the page is a story of small steps, not one 200-line monster.",
      def: "Decomposition: break a problem into small single-purpose functions with descriptive names; each does one thing, is independently testable, and composes into the whole.",
      code: "DON'T: one 200-line doEverything()\n\nDO: small, nameable steps\n\nfunction inStock(p)      { return p.stock; }\nfunction priceLine(p)    {\n  return p.name + \" — $\" + p.price;\n}\nfunction renderList(items, el) {\n  el.innerHTML = \"\";\n  items.forEach(item => {\n    const li = document.createElement(\"li\");\n    li.textContent = item;\n    el.appendChild(li);\n  });\n}\n\n// the page is now a recipe:\nconst lines = products.filter(inStock)\n                      .map(priceLine);\nrenderList(lines, list);\n\nReadable = testable = reusable.",
      out: { web: { h: "<p id=\"o\" style=\"font:13px monospace;white-space:pre-wrap\"></p>", c: "body{font-family:sans-serif;background:#faf7f0;color:#222;padding:24px;margin:0}", j: "function inStock(p){return p.stock} function priceLine(p){return p.name+' — $'+p.price} function total(lines, prices){return prices.filter(inStock).reduce((s,p)=>s+p.price,0)} const products=[{name:'Tea',price:2,stock:true},{name:'Milk',price:1,stock:false},{name:'Coffee',price:4,stock:true}]; const lines=products.filter(inStock).map(priceLine); document.getElementById('o').textContent=lines.join('\\n')+'\\n\\nTotal (small functions did this): $'+total(lines,products);" } },
      flow: ["one thing per function", "name = a sentence", "small = testable", "compose into the page"],
      task: "Take a 30-line script you've written (or the data-flow lesson's) and split it into at least four small functions, each nameable in a sentence. Re-run it — same behavior, but now point at one line and say which function owns that behavior.",
      mistake: "Functions named by how they work (processData2, handleStuff) instead of what they do (inStock, priceLine). And 'and' in the name (validateAndSaveAndNotify) — that's three jobs; split until the name is a single verb phrase.",
      tip: "The test: can you unit-test it without the rest of the page? A pure function (inputs in, value out, no DOM) is trivially testable and reusable. Push logic into pure functions and let the DOM-touching code be thin glue.",
      challenge: "Refactor a function that reads localStorage, parses JSON, validates the shape, and renders the list — into four functions. Which one is impure (touches the outside world), and which three could be tested with plain inputs and expected outputs?" },

    { t: "Project: build a working to-do app",
      text: "The JavaScript capstone, combining everything: a form (submit + preventDefault), an array of objects (the data), localStorage (persistence), the DOM (rendering), and small named functions (structure). Features: add a task, mark done (classList), delete, persist across refreshes, and a remaining-count. The rule that makes it work: the array is the source of truth; the DOM is always re-rendered from it.",
      def: "A to-do app: form input, array of {text, done} as the single source of truth, localStorage for persistence, DOM re-rendering from data, and small functions per action.",
      code: "SPEC (your checklist):\n[ ] form: submit + preventDefault\n[ ] data: todos = [{text, done}]\n[ ] load/save: localStorage + JSON\n[ ] render: rebuild the list from\n    todos (always)\n[ ] actions: add, toggle, delete\n[ ] count: \"3 left\"\n[ ] survives a refresh\n[ ] functions: one thing each\n\nEvery tool from the track.\nData in -> transform -> DOM out.\nShip it.",
      out: { web: { h: "<form id=\"f\" style=\"display:flex;gap:8px;margin-bottom:12px\"><input id=\"i\" placeholder=\"add a task…\" style=\"flex:1;padding:10px;border:1px solid #ccc;border-radius:8px\"><button type=\"submit\" style=\"padding:10px 16px;border:0;border-radius:8px;background:#14171f;color:#f5b23d;font-weight:bold;cursor:pointer\">Add</button></form><ul id=\"list\" style=\"list-style:none;padding:0;margin:0 0 8px;font:14px sans-serif\"></ul><p id=\"c\" style=\"font-size:12px;color:#888\"></p>", c: "body{font-family:sans-serif;background:#faf7f0;color:#222;padding:24px;margin:0;max-width:420px} .todo{display:flex;align-items:center;gap:8px;padding:10px;border:1px solid #e5e0d5;border-radius:8px;margin-bottom:6px;background:#fff} .todo.done span{text-decoration:line-through;color:#999} .del{margin-left:auto;border:0;background:none;color:#c0392b;cursor:pointer;font-size:16px}", j: "let todos=JSON.parse(localStorage.getItem('meen-todos')||'[]'); const list=document.getElementById('list'); const save=()=>localStorage.setItem('meen-todos',JSON.stringify(todos)); function render(){ list.innerHTML=''; todos.forEach((t,i)=>{ const li=document.createElement('li'); li.className='todo'+(t.done?' done':''); const span=document.createElement('span'); span.textContent=t.text; const del=document.createElement('button'); del.className='del'; del.textContent='\\u00d7'; del.onclick=()=>{todos.splice(i,1);save();render();}; li.onclick=(e)=>{if(e.target===del)return; t.done=!t.done; save(); render();}; li.append(span,del); list.appendChild(li); }); const left=todos.filter(t=>!t.done).length; document.getElementById('c').textContent=todos.length? left+' of '+todos.length+' left':'all clear'; } document.getElementById('f').addEventListener('submit',e=>{ e.preventDefault(); const v=document.getElementById('i').value.trim(); if(!v)return; todos.push({text:v,done:false}); document.getElementById('i').value=''; save(); render(); }); render();" } },
      flow: ["form adds to data", "data = source of truth", "localStorage persists", "DOM re-renders", "every action: mutate -> save -> render"],
      task: "Build the app from the spec. Then add two features of your choice (clear completed, a due date, filter all/active/done). For each, you should only touch: one data field, one render branch, one action function. If you're editing the render in five places, your structure is fighting you.",
      mistake: "Updating the DOM piecemeal (adding a <li> on add, flipping a class on toggle, deleting a node on delete) instead of re-rendering from the data — it works until the third feature, then the DOM and data disagree. The rule: mutate the array, save, re-render. Every time.",
      tip: "This app is the template for everything: a chat list, a contacts app, a kanban board — all are 'array of objects + form + render'. Master this pattern once and most frontend projects are just a bigger version of it.",
      challenge: "Add a 'sort by done' toggle that re-sorts the array and re-renders. Then answer: does the sort persist? If not, where in the pipeline would you store the sort preference so it does? (You now know the answer pattern: it's just another key in localStorage.)" }
  ]
};
